using Microsoft.AspNetCore.Authorization;
using Microsoft.AspNetCore.Mvc;
using SolutionOne_BusinessLogicLayer.Services.Canteen_Management.Interface;
using SolutionOne_Core.CanteenManagementModels.MealBooking;
using SolutionOne_Core.CommonModels.RBAC;
using SolutionOneWebPortal.ControllerDecorators;

namespace SolutionOneWebPortal_API.Controllers.Canteen_Management;

/// <summary>Meal booking for the canteen mobile app. Every action works on the logged-in employee only.</summary>
[Authorize]
[Route("api/[controller]")]
[ApiController]
public class MealBookingController : ControllerBase
{
    private readonly IMealBookingService _service;

    public MealBookingController(IMealBookingService service)
    {
        _service = service;
    }

    [HttpGet("GetMyBookings")]
    [Permission(Modules.MealBooking, Actions.View)]
    public async Task<IActionResult> GetMyBookings([FromQuery] DateOnly? fromDate, [FromQuery] DateOnly? toDate)
    {
        var (response, data) = await _service.GetMyBookingsAsync(fromDate, toDate);
        return StatusCode((int)response.Status, new
        {
            response.IsSuccess,
            response.Message,
            Data = data
        });
    }

    [HttpPost("BookMeals")]
    [Permission(Modules.MealBooking, Actions.Create)]
    public async Task<IActionResult> BookMeals([FromBody] BookMealsRequest request)
    {
        var (response, data) = await _service.BookMealsAsync(request);
        return StatusCode((int)response.Status, new
        {
            response.IsSuccess,
            response.Message,
            Data = data
        });
    }

    [HttpPost("CancelMeals")]
    [Permission(Modules.MealBooking, Actions.Delete)]
    public async Task<IActionResult> CancelMeals([FromBody] CancelMealsRequest request)
    {
        var (response, data) = await _service.CancelMealsAsync(request);
        return StatusCode((int)response.Status, new
        {
            response.IsSuccess,
            response.Message,
            Data = data
        });
    }
}

