namespace SolutionOne_Core.CanteenManagementModels.MealBooking;

/// <summary>Values stored in HR_CMS_MealBooking.Status.</summary>
public static class MealBookingStatuses
{
    public const string Booked = "Booked";
    public const string Cancelled = "Cancelled";
}

/// <summary>Per-meal outcome of BookMeals.</summary>
public static class BookMealResultStatuses
{
    public const string Booked = "Booked";
    public const string AlreadyBooked = "Already booked";
    public const string NoMenu = "No menu that day";
    public const string BookingClosed = "Booking closed";
    public const string InvalidMealSession = "Invalid meal session";
}

/// <summary>Per-booking outcome of CancelMeals.</summary>
public static class CancelMealResultStatuses
{
    public const string Cancelled = "Cancelled";
    public const string TooLate = "Too late";
    public const string NotFound = "Not found";
}

/// <summary>appsettings.json "MealBooking". Kept in config for now; may move to a table later.
/// Nothing about the ordering deadline is here: when ordering closes belongs to each meal session
/// (HR_CMS_MealSession.OrderCutoffTime / OrderCutoffDaysBefore) and how far back it may be set belongs to
/// HR_CMS_Config.MaxOrderCutoffDaysBefore - both in the database, both changeable without a restart.</summary>
public class MealBookingSettings
{
    public const string SectionName = "MealBooking";

    /// <summary>Most dates one BookMeals request may carry.</summary>
    public int MaxDatesPerRequest { get; set; } = 31;

    /// <summary>Longest fromDate..toDate range GetMyBookings accepts, in days.</summary>
    public int MaxRangeDays { get; set; } = 92;

    /// <summary>Time zone of the canteen when no branch/company entry matches. Windows ("India Standard Time")
    /// or IANA ("Asia/Kolkata") ids both work on either OS.</summary>
    public string DefaultTimeZoneId { get; set; } = "India Standard Time";

    /// <summary>Time zone per company, keyed by CompanyMasterId.</summary>
    public Dictionary<string, string> CompanyTimeZones { get; set; } = new();

    /// <summary>Time zone per branch, keyed by BranchMasterId. Wins over the company entry.</summary>
    public Dictionary<string, string> BranchTimeZones { get; set; } = new();
}

public class MealBookingModel
{
    public long BookingId { get; set; }
    public DateOnly MealDate { get; set; }
    public int MSessionId { get; set; }
    public string SessionName { get; set; } = string.Empty;
    public string CanteenFacilityType { get; set; } = string.Empty;
    public decimal EmployeeShare { get; set; }
    public decimal CompanyShare { get; set; }
    /// <summary>In the canteen's local time.</summary>
    public DateTime BookedOn { get; set; }
}

public class BookMealsRequest
{
    public List<int> MSessionIds { get; set; } = new();
    public List<DateOnly> Dates { get; set; } = new();
}

public class BookMealResult
{
    public DateOnly MealDate { get; set; }
    public int MSessionId { get; set; }
    public string SessionName { get; set; } = string.Empty;
    public string Status { get; set; } = string.Empty;
    public long? BookingId { get; set; }
    public decimal? EmployeeShare { get; set; }
    public decimal? CompanyShare { get; set; }
    public string Message { get; set; } = string.Empty;
}

public class CancelMealsRequest
{
    public List<long> BookingIds { get; set; } = new();
}

public class CancelMealResult
{
    public long BookingId { get; set; }
    public string Status { get; set; } = string.Empty;
    public string Message { get; set; } = string.Empty;
}

