/// <summary>Values for HrEmployeeMaster.CanteenFacilityType. A Daily employee is charged the
/// meal session's CompanyShare/EmployeeShare; an Adhoc employee the AdhocCompanyShare/AdhocEmployeeShare.</summary>
public static class CanteenFacilityTypes
{
    public const string Daily = "Daily";
    public const string Adhoc = "Adhoc";

    public static bool IsValid(string? value) => value == Daily || value == Adhoc;
}

public class MealSessionModel
{
    public int MSessionId { get; set; }
    public int SessionNameId { get; set; }
    public string SessionName { get; set; } = string.Empty;
    public string StartTime { get; set; } = string.Empty;
    public string EndTime { get; set; } = string.Empty;
    // Ordering deadline
    public string OrderCutoffTime { get; set; } = string.Empty;
    public int OrderCutoffDaysBefore { get; set; }
    /// <summary>The deadline in words, e.g. "11:59 PM the day before the meal", so every screen says it
    /// the same way.</summary>
    public string OrderCutoffDescription { get; set; } = string.Empty;
    public bool IsActive { get; set; }
    // Daily rate
    public decimal CompanyShare { get; set; }
    public decimal EmployeeShare { get; set; }
    // Adhoc rate
    public decimal AdhocCompanyShare { get; set; }
    public decimal AdhocEmployeeShare { get; set; }
}

