namespace SolutionOne_BusinessLogicLayer.Services.Canteen_Management.Implementation;

public class MealBookingService : IMealBookingService
{
    // Hard ceiling on one CancelMeals request; BookMeals is bounded by MaxDatesPerRequest x sessions.
    private const int MaxBookingIdsPerRequest = 200;

    private readonly IMealBookingRepository _repository;
    private readonly IMealSessionRepository _mealSessionRepository;
    private readonly IRequestMetadata _meta;
    private readonly MealBookingSettings _settings;
    private readonly TimeProvider _clock;
    private readonly ILogger<MealBookingService> _logger;

    public MealBookingService(
        IMealBookingRepository repository,
        IMealSessionRepository mealSessionRepository,
        IRequestMetadata meta,
        IOptions<MealBookingSettings> settings,
        TimeProvider clock,
        ILogger<MealBookingService> logger)
    {
        _repository = repository;
        _mealSessionRepository = mealSessionRepository;
