import { inject } from '@angular/core';
import { CanActivateFn, Router } from '@angular/router';
import { AuthService } from './auth.service';
import { ToastService } from './toaster.service';

/**
 * For screens that are about "me as an employee" (my statement, my tasks, my trainings ...): a login user that
 * is not linked to an employee has nothing to show there, and the page would just come up empty. Say so, and
 * stay where the user was instead of opening a dead page.
 *
 * Only add this to screens that really are personal. A screen where an employee is PICKED (an HR user applying
 * on someone's behalf, a master, a report) works for an account with no employee and must not be guarded.
 */
export const canActivateEmployeeOnly: CanActivateFn = () => {
  const auth = inject(AuthService);
  if (auth.hasEmployee()) {
    return true;
  }

  const router = inject(Router);
  const toast = inject(ToastService);
  const who = (localStorage.getItem('userName') ?? '').trim();
  toast.warning(
    `This screen is for employees. ${who ? `"${who}" is` : 'Your account is'} not linked to an employee profile, ` +
      'so there is nothing to show here. Ask an administrator to link the account to an employee if it should have one.',
  );

  // Opened directly (page reload / typed URL) there is no page to stay on: fall back to the dashboard.
  return router.navigated ? false : router.parseUrl('/my-dashboard');
};

