using SolutionOne_Core.CanteenManagementModels.MealBooking;
using SolutionOne_DataAccessLayer.Entities;
using SolutionOne_DataAccessLayer.Repositories.Canteen_Management.Interface;

namespace SolutionOne_DataAccessLayer.Repositories.Canteen_Management.Implementation;

public class MealBookingRepository : IMealBookingRepository
{
    private readonly HrmsystemContext _context;

    public MealBookingRepository(HrmsystemContext context)
    {
        _context = context;
    }

    public Task<List<HrCmsMealBooking>> GetBookedAsync(long employeeMasterId, DateOnly fromDate, DateOnly toDate)
    {
        return _context.HrCmsMealBookings
            .AsNoTracking()
            .Include(x => x.MealSession!)
                .ThenInclude(m => m.SessionNameNavigation)
            .Where(x => x.EmployeeMasterId == employeeMasterId
                        && x.Status == MealBookingStatuses.Booked
                        && x.MealDate >= fromDate && x.MealDate <= toDate)
            .OrderBy(x => x.MealDate)
            .ThenBy(x => x.MealSession!.StartTime)
            .ToListAsync();
    }

    public async Task<HashSet<(DateOnly MealDate, int MSessionId)>> GetBookedKeysAsync(long employeeMasterId, IReadOnlyCollection<DateOnly> dates, IReadOnlyCollection<int> mSessionIds)
    {
        var rows = await _context.HrCmsMealBookings
            .AsNoTracking()
            .Where(x => x.EmployeeMasterId == employeeMasterId
                        && x.Status == MealBookingStatuses.Booked
                        && dates.Contains(x.MealDate)
                        && mSessionIds.Contains(x.MSessionId))
            .Select(x => new { x.MealDate, x.MSessionId })
            .ToListAsync();

        return rows.Select(x => (x.MealDate, x.MSessionId)).ToHashSet();
    }

    public async Task<HashSet<(DateOnly MealDate, int MSessionId)>> GetMenuDaysAsync(IReadOnlyCollection<DateOnly> dates, IReadOnlyCollection<int> mSessionIds)
    {
        if (dates.Count == 0 || mSessionIds.Count == 0)
            return new HashSet<(DateOnly, int)>();

        var from = dates.Min().ToDateTime(TimeOnly.MinValue);
        var toExclusive = dates.Max().AddDays(1).ToDateTime(TimeOnly.MinValue);

        var rows = await _context.HrCmsMenuPlans
            .AsNoTracking()
            .Where(x => x.IsActive
                        && mSessionIds.Contains(x.MealTypeId)
                        && x.PlanDate >= from && x.PlanDate < toExclusive)
            .Select(x => new { x.PlanDate, x.MealTypeId })
            .Distinct()
            .ToListAsync();

        var wanted = dates.ToHashSet();
        return rows
            .Select(x => (MealDate: DateOnly.FromDateTime(x.PlanDate), MSessionId: x.MealTypeId))
            .Where(x => wanted.Contains(x.MealDate))
            .ToHashSet();
    }

    public async Task<List<bool>> AddBookingsAsync(IReadOnlyList<HrCmsMealBooking> bookings)
    {
        if (bookings.Count == 0)
            return new List<bool>();

        // Normal case: one round trip for the whole request.
        _context.HrCmsMealBookings.AddRange(bookings);
        try
        {
            await _context.SaveChangesAsync();
            return bookings.Select(_ => true).ToList();
        }
        catch (DbUpdateException ex) when (IsDuplicateActiveBooking(ex))
        {
            // Another request booked one of these meals between our check and the insert. Nothing
            // was saved (SaveChanges is one transaction) - insert row by row so only that meal is lost.
            foreach (var booking in bookings)
                _context.Entry(booking).State = EntityState.Detached;
        }

        var inserted = new List<bool>(bookings.Count);
        foreach (var booking in bookings)
        {
            booking.BookingId = 0;
            _context.HrCmsMealBookings.Add(booking);
            try
            {
                await _context.SaveChangesAsync();
                inserted.Add(true);
            }
            catch (DbUpdateException ex) when (IsDuplicateActiveBooking(ex))
            {
                _context.Entry(booking).State = EntityState.Detached;
                inserted.Add(false);
            }
        }
        return inserted;
    }

    public Task<List<HrCmsMealBooking>> GetBookedByIdsAsync(long employeeMasterId, IReadOnlyCollection<long> bookingIds)
    {
        return _context.HrCmsMealBookings
            .Include(x => x.MealSession)
            .Where(x => x.EmployeeMasterId == employeeMasterId
                        && x.Status == MealBookingStatuses.Booked
                        && bookingIds.Contains(x.BookingId))
            .ToListAsync();
    }

    public Task SaveChangesAsync() => _context.SaveChangesAsync();

    // 2601 = duplicate key in a unique index, 2627 = unique constraint.
    private static bool IsDuplicateActiveBooking(DbUpdateException ex) =>
        ex.InnerException is SqlException sql
        && (sql.Number == 2601 || sql.Number == 2627)
        && sql.Message.Contains("UX_HR_CMS_MealBooking_ActiveMeal", StringComparison.OrdinalIgnoreCase);
}

