            .OrderBy(x => x.SessionNameNavigation != null ? x.SessionNameNavigation.SessionName : string.Empty)
            .ToListAsync();
    }

    public Task<HrCmsMealSession?> GetByIdAsync(int id)
    {
        return _context.HrCmsMealSessions
            .Include(x => x.SessionNameNavigation)
            .FirstOrDefaultAsync(x => x.MSessionId == id);
    }

    public Task<List<HrCmsSessionName>> GetAllSessionNamesAsync()
    {
        return _context.HrCmsSessionNames
            .AsNoTracking()
            .Where(x => x.IsActive)
            .OrderBy(x => x.SortOrder)
            .ThenBy(x => x.SessionName)
            .ToListAsync();
    }

    public Task<HrCmsSessionName?> GetSessionNameByIdAsync(int sessionNameId)
    {
        return _context.HrCmsSessionNames
            .AsNoTracking()
            .FirstOrDefaultAsync(x => x.IsActive && x.SessionNameId == sessionNameId);
    }

    public Task<bool> IsValidSessionNameIdAsync(int sessionNameId)
    {
        return _context.HrCmsSessionNames.AnyAsync(x => x.IsActive && x.SessionNameId == sessionNameId);
    }

    public Task<bool> ExistsBySessionNameIdAsync(int sessionNameId, int? exceptMSessionId = null)
    {
        var query = _context.HrCmsMealSessions.Where(x => x.SessionNameId == sessionNameId);
        if (exceptMSessionId.HasValue)
            query = query.Where(x => x.MSessionId != exceptMSessionId.Value);

        return query.AnyAsync();
    }

    public async Task AddAsync(HrCmsMealSession entity)
    {
        _context.HrCmsMealSessions.Add(entity);
        await _context.SaveChangesAsync();
    }

    public async Task UpdateAsync(HrCmsMealSession entity)
    {
        _context.HrCmsMealSessions.Update(entity);
        await _context.SaveChangesAsync();
    }

    public async Task<bool> DeleteAsync(int id)
    {
        var entity = await _context.HrCmsMealSessions.FirstOrDefaultAsync(x => x.MSessionId == id);
        if (entity == null)
            return false;

        _context.HrCmsMealSessions.Remove(entity);
        await _context.SaveChangesAsync();
        return true;
    }

