using SolutionOne_Core.CanteenManagementModels.MealSession;
using SolutionOne_DataAccessLayer.Entities;

namespace SolutionOne_BusinessLogicLayer.Services.Canteen_Management.Implementation;

/// <summary>The one place that decides what an employee pays for a meal session, shared by
/// GetEmployeeMealRates and meal booking so both always charge the same.</summary>
internal static class CanteenMealRates
{
    public const string FacilityNotEnabledMessage = "Canteen facility is not enabled for this employee.";

    /// <summary>The employee's Meal Plan. Older employees saved before CanteenFacilityType existed default to Daily.</summary>
    public static string FacilityTypeOf(HrEmployeeMaster employee) =>
        employee.CanteenFacilityType == CanteenFacilityTypes.Adhoc ? CanteenFacilityTypes.Adhoc : CanteenFacilityTypes.Daily;

    /// <summary>Daily employees pay CompanyShare/EmployeeShare, Adhoc employees AdhocCompanyShare/AdhocEmployeeShare.</summary>
    public static (decimal CompanyShare, decimal EmployeeShare) For(HrCmsMealSession session, string facilityType) =>
        facilityType == CanteenFacilityTypes.Adhoc
            ? (session.AdhocCompanyShare, session.AdhocEmployeeShare)
            : (session.CompanyShare, session.EmployeeShare);
}

