using System.Net;
using SolutionOne_BusinessLogicLayer.Services.Canteen_Management.Interface;
using SolutionOne_Core.CanteenManagementModels.CanteenDashboard;
using SolutionOne_Core.CommonModels;
using SolutionOne_DataAccessLayer.Repositories.Canteen_Management.Interface;

namespace SolutionOne_BusinessLogicLayer.Services.Canteen_Management.Implementation;

public class CanteenDashboardService : ICanteenDashboardService
{
    // Publish statuses observed in MenuPublishService (Completed/Failed). "Failed" means the publish
    // attempt did not actually reach recipients, so it is excluded from the recipient-count proxy.
    private static readonly string[] ExcludedPublishStatuses = { "Failed" };

    private readonly ICanteenDashboardRepository _repository;

    public CanteenDashboardService(ICanteenDashboardRepository repository)
    {
        _repository = repository;
    }

    public async Task<(ResponseModel, CanteenDashboardSummaryModel?)> GetSummaryAsync()
    {
        var response = new ResponseModel { IsSuccess = true, Status = HttpStatusCode.OK };

        var today = DateTime.Today;
        var weekStart = today.AddDays(-6);

        var publishes = await _repository.GetPublishesOverlappingRangeAsync(weekStart, today);
        var eligiblePublishes = publishes
            .Where(x => !ExcludedPublishStatuses.Contains(x.PublishStatus))
            .ToList();

        var weeklyTrend = new List<CanteenDashboardTrendPointModel>();
        for (var i = 0; i < 7; i++)
        {
            var date = weekStart.AddDays(i);
            var count = eligiblePublishes
                .Where(x => x.FromDate.Date <= date && x.ToDate.Date >= date)
                .Sum(x => x.TotalRecipients);

            weeklyTrend.Add(new CanteenDashboardTrendPointModel
            {
                Date = date,
                Count = count
            });
        }

        var todaysMealCount = weeklyTrend.Last().Count;
        var menuPublishedThisWeek = await _repository.GetDistinctPublishCountCreatedInRangeAsync(weekStart, today);

        var summary = new CanteenDashboardSummaryModel
        {
            TodaysMealCount = todaysMealCount,
            MenuPublishedThisWeek = menuPublishedThisWeek,
            WeeklyTrend = weeklyTrend
        };

        return (response, summary);
    }
}
