namespace SolutionOne_Core.CanteenManagementModels.CanteenDashboard;

// NOTE: There is no per-employee meal-consumption/order table in this schema, so TodaysMealCount and
// WeeklyTrend counts are proxies derived from HrCmsMenuPublish.TotalRecipients (recipient counts of
// published menus), not actual meal consumption/order counts.
public class CanteenDashboardSummaryModel
{
    public int TodaysMealCount { get; set; }
    public int MenuPublishedThisWeek { get; set; }
    public List<CanteenDashboardTrendPointModel> WeeklyTrend { get; set; } = new();
}

public class CanteenDashboardTrendPointModel
{
    public DateTime Date { get; set; }
    public int Count { get; set; }
}
