namespace SolutionOne_Core.CommonModels.RBAC
{
	public static class Modules
	{
		public const string LeaveApplication = "LeaveApplication";
		public const string AttendanceAdjustment = "AttendanceAdjustment";
		public const string Employee = "Employee";
		public const string User = "User";
		public const string UserRights = "UserRights";
		// A module is identified by the HR_MenuItems row it belongs to: either its MainMenu code (as the
		// older constants here) or its NavigateUrl. Both are accepted by the permission checks - the
		// admin screens below use the route because it is stable and unique.
		public const string RoleAdministration = "/admin/rbac";
		public const string HrConfig = "/admin/hr-config";
		// User Master screen: who may list, create, edit and delete logins.
		public const string UserMaster = "/admin/user";
		// Salary Head Master screen (Query / Stored Procedure / AI-assisted formulas run SQL, so they are guarded).
		public const string SalaryHead = "/payroll/salary-head";
		// Travel Management screens, named by route. The three older MainMenu-code constants below
		// (TravelPayment / TravelSettlement / ApproveTravelExpense) are kept because the controller-level
		// [Permission] attributes on those screens already use them - the service marks use the same ones
		// so both layers always agree.
		public const string TripRequest = "/travel-management/trip-request";
		public const string TripApproval = "/travel-management/trip-approval";
		public const string TravelPolicy = "/travel-management/travel-policy";
		public const string TripExpenseSubmit = "/travel-management/trip-expense-submit";
		public const string TravelPayment = "Advance Payment";
		public const string TravelSettlement = "Expense Settlement";
		public const string ApproveTravelExpense = "Approve Expense";
		// Canteen mobile app: an employee booking / cancelling their own meals. No web screen - the
		// HR_MenuItems row only carries the permission (Migration_CanteenMealBooking_20261023.sql).
		public const string MealBooking = "/canteen-management/meal-booking";
	}

	public static class Actions
	{
		public const string View = "VIEW";
		public const string Create = "CREATE";
		public const string Update = "UPDATE";
		public const string Delete = "DELETE";
		// No Approve action: approving is the Approval Engine's job, not a role permission (the APPROVE row
		// is removed from HR_MenuActions by Migration_RemoveApproveAction_20261009.sql).
		public const string Reject = "REJECT";
		public const string Export = "EXPORT";
		public const string Import = "IMPORT";
		public const string Print = "PRINT";
	}

	// Shared with PermissionFilter (SolutionOneWebPortal.ControllerDecorators) so cache writes/evictions use identical keys.
	public static class PermissionCacheKeys
	{
		public static string Version(int userId) => $"PermissionVersion_{userId}";
		public static string Permissions(int userId) => $"UserPermissions_{userId}";
	}
}

