﻿using System.Net;

namespace SolutionOne_Core.CommonModels
{
    public class ResponseModel
    {
        public bool IsSuccess { get; set; }
        public HttpStatusCode Status { get; set; }
        public string? Message { get; set; }
        public object? Data { get; set; }
        public object? DynamicData { get; set; }

        /// <summary>Field-level validation errors, keyed by camelCase field name, ASP.NET
        /// ValidationProblemDetails-style. Null when the failure isn't tied to a specific field
        /// (e.g. "Employee not found.").</summary>
        public Dictionary<string, List<string>>? Errors { get; set; }

        public ResponseModel FastRet
        (
         bool success, HttpStatusCode code, string msg, object? data, object? dyn
         )
        {
            IsSuccess = success;
            Status = code;
            Message = msg;
            Data = data;
            DynamicData = dyn;
            return this;
        }
    }


