=== IRequestMetadata ===
﻿namespace SolutionOne_BusinessLogicLayer.Services.Common.Interface
{
    public interface IRequestMetadata
    {
        long CompanyId { get; }
        long BranchId { get; }
        long UserId { get; }
        long EmployeeMasterId { get; }
        string MachineName { get; }
        string UserRole { get; }

        /// <summary>
        /// Non-numeric-role companion to RoleId - 0 until HR_UserMaster.RoleId is added and mapped
        /// in LoginService (same caveat the old TravelUserContext carried). Tolerant by nature:
        /// absent/unparseable just means "no role ID on this token", not an error worth throwing for.
        /// </summary>
        long RoleId { get; }

        /// <summary>
        /// Every role claim on the token (ASP.NET's own ClaimTypes.Role entries), with the UserRole
        /// claim folded in at the front if it isn't already present. Empty, never throws, when the
        /// caller has no role claims at all - multi-role support UserRole alone doesn't give you.
        /// </summary>
        IReadOnlyList<string> RoleNames { get; }

        /// <summary>
        /// Tolerant companions to the throwing properties above, for call sites where "this claim is
        /// missing" is a legitimate, expected state to branch on (e.g. an Admin login with no
        /// employee record) rather than something to treat as an error. Each returns false (and
        /// default(long) in the out parameter) instead of throwing MissingClaimException.
        /// </summary>
        bool TryGetCompanyId(out long companyId);
        bool TryGetBranchId(out long branchId);
        bool TryGetUserId(out long userId);
        bool TryGetEmployeeMasterId(out long employeeMasterId);
    }
}

