namespace SolutionOne_Core.CanteenManagementModels.MealBooking;

/// <summary>What one cell of the planner is: the single word a screen switches on. Every other field on
/// the cell describes this state, it never contradicts it.</summary>
public static class MealPlannerCellStatuses
{
    /// <summary>Free to book right now.</summary>
    public const string Bookable = "Bookable";
    /// <summary>The employee already has this meal. Cancellable until the same deadline.</summary>
    public const string Booked = "Booked";
    /// <summary>The deadline has passed - can be neither booked nor cancelled.</summary>
    public const string Closed = "Closed";
    /// <summary>Nothing is being cooked for this session that day.</summary>
    public const string NoMenu = "NoMenu";
    /// <summary>There is a menu and the deadline has not passed, but this employee has no canteen facility.</summary>
    public const string NotEligible = "NotEligible";
}

/// <summary>One meal session as a column/row heading: what it is called, when it is served and what this
/// employee pays for it. The rate is already resolved for the employee's Meal Plan, so no screen has to
/// know the Daily/Adhoc rule.</summary>
public class MealPlannerSessionModel
{
    public int MSessionId { get; set; }
    public string SessionName { get; set; } = string.Empty;
    public string StartTime { get; set; } = string.Empty;
    public string EndTime { get; set; } = string.Empty;
    /// <summary>"11:59 PM the day before the meal" - the standing rule, not a date.</summary>
    public string OrderCutoffDescription { get; set; } = string.Empty;
    public decimal CompanyShare { get; set; }
    public decimal EmployeeShare { get; set; }
}

/// <summary>One meal on one day for the logged-in employee: everything the screen needs to draw the cell
/// and to decide whether tapping it does anything.</summary>
public class MealPlannerCellModel
{
    public int MSessionId { get; set; }
    public string SessionName { get; set; } = string.Empty;
    /// <summary>What is on the menu, in the order the items were planned. Empty when there is no menu.</summary>
    public List<string> Items { get; set; } = new();
    public bool HasMenu { get; set; }
    public bool IsClosed { get; set; }
    /// <summary>The deadline for this one meal as a date an employee can check: "09:30 AM on 25 Oct 2026".</summary>
    public string ClosesAt { get; set; } = string.Empty;
    public decimal CompanyShare { get; set; }
    public decimal EmployeeShare { get; set; }
    public long? BookingId { get; set; }
    public bool IsBooked { get; set; }
    /// <summary>True only when BookMeals would accept this meal right now.</summary>
    public bool CanBook { get; set; }
    /// <summary>True only when CancelMeals would accept this booking right now.</summary>
    public bool CanCancel { get; set; }
    /// <summary>One of <see cref="MealPlannerCellStatuses"/>.</summary>
    public string Status { get; set; } = string.Empty;
    /// <summary>The sentence to print in the cell. Worded the same as the matching BookMeals / CancelMeals
    /// reply, so the screen never promises something the booking call then refuses.</summary>
    public string StatusMessage { get; set; } = string.Empty;
}

/// <summary>One day of the planner.</summary>
public class MealPlannerDayModel
{
    public DateOnly MealDate { get; set; }
    /// <summary>"Mon".</summary>
    public string DayLabel { get; set; } = string.Empty;
    /// <summary>"27 Oct".</summary>
    public string DateLabel { get; set; } = string.Empty;
    public bool IsToday { get; set; }
    /// <summary>Before today in the canteen's time zone.</summary>
    public bool IsPast { get; set; }
    /// <summary>One cell per active meal session, in serving order. Always the same length and order as
    /// <see cref="MealPlannerModel.Sessions"/>, so a grid can index straight into it.</summary>
    public List<MealPlannerCellModel> Meals { get; set; } = new();
    /// <summary>Counts for the day strip on a phone, where the cells themselves are off screen.</summary>
    public int BookedCount { get; set; }
    public int BookableCount { get; set; }
}

/// <summary>Everything the meal booking screen needs for one date range, in one call: the menu, this
/// employee's rates, which meals are already booked and which deadlines have passed. The deadline is
/// decided here rather than on the client because it is read in the canteen's own time zone - a browser
/// working it out from its own clock would show a different rule than the one BookMeals enforces.</summary>
public class MealPlannerModel
{
    public DateOnly FromDate { get; set; }
    public DateOnly ToDate { get; set; }
    /// <summary>Today in the canteen's time zone, not the client's.</summary>
    public DateOnly Today { get; set; }
    public bool IsCanteenFacility { get; set; }
    /// <summary>"Daily" or "Adhoc" - which rate the shares below came from.</summary>
    public string CanteenFacilityType { get; set; } = string.Empty;
    /// <summary>Set only when the employee has no canteen facility: the one banner to show above the grid.</summary>
    public string? FacilityMessage { get; set; }
    public List<MealPlannerSessionModel> Sessions { get; set; } = new();
    public List<MealPlannerDayModel> Days { get; set; } = new();
}
