using SolutionOne_Core.CanteenManagementModels.MealBooking;
using SolutionOne_DataAccessLayer.Entities;

namespace SolutionOne_DataAccessLayer.Repositories.Canteen_Management.Interface;

public interface IMealBookingRepository
{
    /// <summary>The employee's active (Booked) meals between two dates, with the session name.</summary>
    Task<List<HrCmsMealBooking>> GetBookedAsync(long employeeMasterId, DateOnly fromDate, DateOnly toDate);

    /// <summary>(MealDate, MSessionId) pairs the employee already has booked, among the given dates and sessions.</summary>
    Task<HashSet<(DateOnly MealDate, int MSessionId)>> GetBookedKeysAsync(long employeeMasterId, IReadOnlyCollection<DateOnly> dates, IReadOnlyCollection<int> mSessionIds);

    /// <summary>(PlanDate, MSessionId) pairs that have an active menu plan, among the given dates and sessions.</summary>
    Task<HashSet<(DateOnly MealDate, int MSessionId)>> GetMenuDaysAsync(IReadOnlyCollection<DateOnly> dates, IReadOnlyCollection<int> mSessionIds);

    /// <summary>What is on the menu for each (date, session) in the range: the item names, so the planner
    /// can show the food rather than only whether a meal exists. Inactive items are left out - the plan may
    /// still point at an item the canteen has since retired.</summary>
    Task<List<(DateOnly MealDate, int MSessionId, string ItemName)>> GetMenuItemsAsync(DateOnly fromDate, DateOnly toDate, IReadOnlyCollection<int> mSessionIds);

    /// <summary>One page of the Bookings Register, with the totals of the whole filtered set. Spans every
    /// employee, so only a screen that carries the register permission may call it.</summary>
    Task<BookingRegisterModel> GetBookingRegisterAsync(BookingRegisterQuery query, DateOnly fromDate, DateOnly toDate);

    /// <summary>Inserts the bookings. A row that hits the one-active-booking-per-meal index (booked meanwhile
    /// by another request) is skipped; the result says, per row in order, whether it was inserted.</summary>
    Task<List<bool>> AddBookingsAsync(IReadOnlyList<HrCmsMealBooking> bookings);

    /// <summary>The employee's own Booked rows among the ids (tracked, for cancelling).</summary>
    Task<List<HrCmsMealBooking>> GetBookedByIdsAsync(long employeeMasterId, IReadOnlyCollection<long> bookingIds);

    Task SaveChangesAsync();
}

