import io
p = 'Implementation/MealBookingRepository.cs'
s = io.open(p, encoding='utf-8-sig').read()

anchor = """    public async Task<List<bool>> AddBookingsAsync(IReadOnlyList<HrCmsMealBooking> bookings)"""

new_methods = '''    public async Task<List<(DateOnly MealDate, int MSessionId, string ItemName)>> GetMenuItemsAsync(DateOnly fromDate, DateOnly toDate, IReadOnlyCollection<int> mSessionIds)
    {
        if (mSessionIds.Count == 0 || toDate < fromDate)
            return new List<(DateOnly, int, string)>();

        var from = fromDate.ToDateTime(TimeOnly.MinValue);
        var toExclusive = toDate.AddDays(1).ToDateTime(TimeOnly.MinValue);

        // MenuPlanId ascending keeps the items of one meal in the order they were planned, which is the
        // order HR typed them into the Menu Plan screen.
        var rows = await _context.HrCmsMenuPlans
            .AsNoTracking()
            .Where(x => x.IsActive
                        && mSessionIds.Contains(x.MealTypeId)
                        && x.PlanDate >= from && x.PlanDate < toExclusive
                        && x.Item != null && x.Item.IsActive)
            .OrderBy(x => x.PlanDate)
            .ThenBy(x => x.MenuPlanId)
            .Select(x => new { x.PlanDate, x.MealTypeId, x.Item!.ItemName })
            .ToListAsync();

        return rows
            .Select(x => (MealDate: DateOnly.FromDateTime(x.PlanDate), MSessionId: x.MealTypeId, x.ItemName))
            .ToList();
    }

    // BookedOn / CancelledOn come back as the UTC instants they are stored as; the service shifts them
    // into the canteen's time zone, the one place that knows which zone that is.
    public async Task<BookingRegisterModel> GetBookingRegisterAsync(BookingRegisterQuery query, DateOnly fromDate, DateOnly toDate)
    {
        var rows = from b in _context.HrCmsMealBookings.AsNoTracking()
                   join e in _context.HrEmployeeMasters.AsNoTracking() on b.EmployeeMasterId equals e.EmployeeMasterId
                   where b.MealDate >= fromDate && b.MealDate <= toDate
                   select new { Booking = b, Employee = e };

        if (query.MSessionId is > 0)
            rows = rows.Where(x => x.Booking.MSessionId == query.MSessionId);

        if (query.EmployeeMasterId is > 0)
            rows = rows.Where(x => x.Booking.EmployeeMasterId == query.EmployeeMasterId);

        if (query.Status == MealBookingStatuses.Booked || query.Status == MealBookingStatuses.Cancelled)
            rows = rows.Where(x => x.Booking.Status == query.Status);

        var search = query.Search?.Trim();
        if (!string.IsNullOrEmpty(search))
        {
            rows = rows.Where(x => x.Employee.Code.Contains(search)
                                   || x.Employee.FirstName.Contains(search)
                                   || x.Employee.LastName.Contains(search));
        }

        var totalCount = await rows.CountAsync();
        var bookedRows = rows.Where(x => x.Booking.Status == MealBookingStatuses.Booked);
        var bookedCount = await bookedRows.CountAsync();

        // Cast to decimal? so an empty set sums to NULL rather than failing to materialise as decimal.
        var totalCompanyShare = await bookedRows.Select(x => (decimal?)x.Booking.CompanyShare).SumAsync() ?? 0m;
        var totalEmployeeShare = await bookedRows.Select(x => (decimal?)x.Booking.EmployeeShare).SumAsync() ?? 0m;

        var page = await rows
            .OrderBy(x => x.Booking.MealDate)
            .ThenBy(x => x.Booking.MealSession!.StartTime)
            .ThenBy(x => x.Employee.Code)
            .Skip((query.Page - 1) * query.PageSize)
            .Take(query.PageSize)
            .Select(x => new BookingRegisterRowModel
            {
                BookingId = x.Booking.BookingId,
                MealDate = x.Booking.MealDate,
                MSessionId = x.Booking.MSessionId,
                SessionName = x.Booking.MealSession!.SessionNameNavigation!.SessionName,
                EmployeeMasterId = x.Employee.EmployeeMasterId,
                EmployeeCode = x.Employee.Code,
                EmployeeName = x.Employee.FirstName + " " + x.Employee.LastName,
                CanteenFacilityType = x.Booking.CanteenFacilityType,
                CompanyShare = x.Booking.CompanyShare,
                EmployeeShare = x.Booking.EmployeeShare,
                Status = x.Booking.Status,
                BookedOn = x.Booking.BookedOnUtc,
                CancelledOn = x.Booking.CancelledOnUtc
            })
            .ToListAsync();

        return new BookingRegisterModel
        {
            FromDate = fromDate,
            ToDate = toDate,
            Page = query.Page,
            PageSize = query.PageSize,
            TotalCount = totalCount,
            BookedCount = bookedCount,
            // Status is only ever Booked or Cancelled, so the remainder is the cancelled rows - one
            // round trip less than counting them.
            CancelledCount = totalCount - bookedCount,
            TotalCompanyShare = totalCompanyShare,
            TotalEmployeeShare = totalEmployeeShare,
            Rows = page
        };
    }

'''

assert s.count(anchor) == 1
s = s.replace(anchor, new_methods + anchor, 1)
io.open(p, 'w', encoding='utf-8').write(s)
print('ok')
