            {"""
assert s.count(old) == 1
s = s.replace(old, new, 1)

# 5. The helper, next to the other private helpers.
old = """    private DateTime UtcNow => _clock.GetUtcNow().UtcDateTime;"""
new = """    /// <summary>The distinct meals a BookMeals request asks for, from whichever of its two shapes was
    /// filled in. Unordered - the caller sorts once it knows when each session is served.</summary>
    private static List<(DateOnly Date, int SessionId)> BuildTargets(BookMealsRequest? request)
    {
        var items = request?.Items ?? new List<MealBookingItemRequest>();
        if (items.Count > 0)
        {
            return items
                .Select(x => (Date: x.MealDate, SessionId: x.MSessionId))
                .Distinct()
                .ToList();
        }

        var dates = (request?.Dates ?? new List<DateOnly>()).Distinct();
        var sessionIds = (request?.MSessionIds ?? new List<int>()).Distinct().ToList();
        return dates
            .SelectMany(date => sessionIds.Select(sessionId => (Date: date, SessionId: sessionId)))
            .ToList();
    }

