                var booking = bookings.TryGetValue(key, out var found) ? found : null;
                var isClosed = nowUtc > OrderDeadlineUtc(date, session, zone);
                var closesAt = MealOrderCutoff.DescribeFor(date, session.OrderCutoffTime, session.OrderCutoffDaysBefore);
                var (companyShare, employeeShare) = CanteenMealRates.For(session, facilityType);

