                    Items = items,
                    HasMenu = items.Count > 0,
                    IsClosed = isClosed,
                    ClosesAt = closesAt,
                    // A booked meal is charged what it cost when it was booked, not today's rate.
                    CompanyShare = booking?.CompanyShare ?? companyShare,
                    EmployeeShare = booking?.EmployeeShare ?? employeeShare,
                    BookingId = booking?.BookingId,
                    IsBooked = booking != null
                };

                // Worded as the matching BookMeals / CancelMeals reply would word it, so the cell never
                // says something the booking call then contradicts. "No menu" is checked before the
                // deadline because it is the truer thing to say: there is nothing to order either way.
                if (booking != null)
