                    cell.Status = MealPlannerCellStatuses.Booked;
                    cell.CanCancel = !isClosed;
                    cell.StatusMessage = isClosed
                        ? $"Booked. This meal can no longer be cancelled - ordering closed at {closesAt}."
                        : $"Booked. Can be cancelled until {closesAt}.";
                }
                else if (items.Count == 0)
                {
                    cell.Status = MealPlannerCellStatuses.NoMenu;
                    cell.StatusMessage = "No menu is planned for this meal on this day.";
                }
                else if (isClosed)
                {
                    cell.Status = MealPlannerCellStatuses.Closed;
                    cell.StatusMessage = $"Ordering for this meal closed at {closesAt}.";
                }
                else if (!employee.IsCanteenFacility)
                {
                    cell.Status = MealPlannerCellStatuses.NotEligible;
                    cell.StatusMessage = CanteenMealRates.FacilityNotEnabledMessage;
                }
                else
                {
                    cell.Status = MealPlannerCellStatuses.Bookable;
                    cell.CanBook = true;
                    cell.StatusMessage = $"Order by {closesAt}.";
                }

                day.Meals.Add(cell);
            }

