    public async Task<(ResponseModel, CanteenBookingCountsModel?)> GetBookingCountsAsync(DateOnly? fromDate, DateOnly? toDate)
    {
        // The canteen's own zone, not the viewer's: "is tomorrow's count final?" is a question about the
        // kitchen's clock. There is no one employee here to narrow it down by branch or company.
        var zone = TimeZoneLookup.Find(_settings.DefaultTimeZoneId)
                   ?? TimeZoneLookup.Find("India Standard Time")
                   ?? TimeZoneInfo.Utc;
        var nowUtc = _clock.GetUtcNow().UtcDateTime;
        var today = DateOnly.FromDateTime(TimeZoneLookup.FromUtc(nowUtc, zone));

        var from = fromDate ?? today;
        var to = toDate ?? from.AddDays(DefaultCountDays - 1);

        if (to < from)
        {
            return (new ResponseModel { IsSuccess = false, Status = HttpStatusCode.BadRequest, Message = "toDate must be on or after fromDate." }, null);
        }

        if (to.DayNumber - from.DayNumber + 1 > _settings.MaxRangeDays)
        {
            return (new ResponseModel
            {
                IsSuccess = false,
                Status = HttpStatusCode.BadRequest,
                Message = $"The date range can be at most {_settings.MaxRangeDays} days."
            }, null);
        }

        var rows = await _repository.GetBookingCountsAsync(from, to);
        var booked = rows.Select(x => x.MSessionId).ToHashSet();

        // An inactive session the kitchen still has bookings for has to be cooked, so it stays in the
        // grid; an inactive one nobody booked is just noise.
        var sessions = (await _mealSessionRepository.GetAllAsync())
            .Where(x => x.IsActive || booked.Contains(x.MSessionId))
            .OrderBy(x => x.StartTime)
            .ToList();

        var byKey = rows
            .GroupBy(x => (x.MealDate, x.MSessionId))
            .ToDictionary(g => g.Key, g => g.ToList());

        var counts = new CanteenBookingCountsModel
        {
            FromDate = from,
            ToDate = to,
            Today = today
        };

        for (var date = from; date <= to; date = date.AddDays(1))
        {
            var day = new CanteenBookingCountDayModel
            {
                MealDate = date,
                DayLabel = date.ToString("ddd", CultureInfo.InvariantCulture),
                DateLabel = date.ToString("dd MMM", CultureInfo.InvariantCulture),
                IsToday = date == today
            };

            foreach (var session in sessions)
            {
                var dayRows = byKey.TryGetValue((date, session.MSessionId), out var found)
                    ? found
                    : new List<CanteenBookingCountRow>();

                day.Sessions.Add(new CanteenBookingCountCellModel
                {
                    MSessionId = session.MSessionId,
                    SessionName = session.SessionNameNavigation?.SessionName ?? string.Empty,
                    TotalMeals = dayRows.Sum(x => x.TotalMeals),
                    DailyCount = dayRows.Where(x => x.CanteenFacilityType != CanteenFacilityTypes.Adhoc).Sum(x => x.TotalMeals),
                    AdhocCount = dayRows.Where(x => x.CanteenFacilityType == CanteenFacilityTypes.Adhoc).Sum(x => x.TotalMeals),
                    CompanyShare = dayRows.Sum(x => x.CompanyShare),
                    EmployeeShare = dayRows.Sum(x => x.EmployeeShare),
                    IsFinal = nowUtc > DeadlineUtc(date, session, zone)
                });
            }

            day.TotalMeals = day.Sessions.Sum(x => x.TotalMeals);
            counts.Days.Add(day);
        }

        // IsFinal is left false on the totals: a range is only ever part settled, so the flag would be
        // claiming something about days it does not hold for.
        counts.SessionTotals = sessions.Select(session =>
        {
            var cells = counts.Days.SelectMany(d => d.Sessions).Where(x => x.MSessionId == session.MSessionId).ToList();
            return new CanteenBookingCountCellModel
            {
                MSessionId = session.MSessionId,
                SessionName = session.SessionNameNavigation?.SessionName ?? string.Empty,
                TotalMeals = cells.Sum(x => x.TotalMeals),
                DailyCount = cells.Sum(x => x.DailyCount),
                AdhocCount = cells.Sum(x => x.AdhocCount),
                CompanyShare = cells.Sum(x => x.CompanyShare),
                EmployeeShare = cells.Sum(x => x.EmployeeShare)
            };
        }).ToList();

        counts.TotalMeals = counts.SessionTotals.Sum(x => x.TotalMeals);
        counts.TotalCompanyShare = counts.SessionTotals.Sum(x => x.CompanyShare);
        counts.TotalEmployeeShare = counts.SessionTotals.Sum(x => x.EmployeeShare);

        return (new ResponseModel { IsSuccess = true, Status = HttpStatusCode.OK }, counts);
    }

    /// <summary>When ordering closed for one meal on one day, in UTC. The same rule MealBookingService
    /// enforces, read through MealOrderCutoff so the two can never drift.</summary>
    private static DateTime DeadlineUtc(DateOnly mealDate, HrCmsMealSession session, TimeZoneInfo zone) =>
        TimeZoneLookup.ToUtc(MealOrderCutoff.LocalDeadline(mealDate, session.OrderCutoffTime, session.OrderCutoffDaysBefore), zone);
}'''

