    [Fact]
    public async Task Each_meal_gets_its_own_outcome()
    {
        var oct26 = Oct25.AddDays(1);
        var oct22 = new DateOnly(2026, 10, 22);
        _bookings.Setup(x => x.GetBookedKeysAsync(EmployeeId, It.IsAny<IReadOnlyCollection<DateOnly>>(), It.IsAny<IReadOnlyCollection<int>>()))
            .ReturnsAsync(new HashSet<(DateOnly, int)> { (oct26, Lunch) });

        var request = new BookMealsRequest { Dates = new() { Oct25, oct26, oct22, new DateOnly(2026, 10, 27) }, MSessionIds = new() { Lunch, Dinner, 99 } };
        var (_, results) = await Service(Utc(2026, 10, 23, 6, 0)).BookMealsAsync(request);

        string StatusOf(DateOnly d, int s) => results.Single(r => r.MealDate == d && r.MSessionId == s).Status;
        Assert.Equal(12, results.Count);
        Assert.Equal(BookMealResultStatuses.Booked, StatusOf(Oct25, Lunch));
        Assert.Equal(BookMealResultStatuses.AlreadyBooked, StatusOf(oct26, Lunch));
        Assert.Equal(BookMealResultStatuses.BookingClosed, StatusOf(oct22, Lunch));
        Assert.Equal(BookMealResultStatuses.NoMenu, StatusOf(new DateOnly(2026, 10, 27), Lunch));
        Assert.Equal(BookMealResultStatuses.InvalidMealSession, StatusOf(Oct25, Dinner));   // inactive
        Assert.Equal(BookMealResultStatuses.InvalidMealSession, StatusOf(Oct25, 99));       // unknown
    }

    [Theory]
    // Lunch is ordered by 09:30 on the day of the meal; 09:30 IST = 04:00 UTC. The deadline itself still counts.
    [InlineData(3, 59, BookMealResultStatuses.Booked)]
    [InlineData(4, 0, BookMealResultStatuses.Booked)]
    [InlineData(4, 1, BookMealResultStatuses.BookingClosed)]
    public async Task A_same_day_deadline_closes_ordering_at_its_own_clock_time(int utcHour, int utcMinute, string expected)
    {
    public async Task My_bookings_rejects_a_reversed_range()
    {
        var (response, _) = await Service(Utc(2026, 10, 23, 6, 0)).GetMyBookingsAsync(Oct25, Oct25.AddDays(-1));

        Assert.Equal(HttpStatusCode.BadRequest, response.Status);
    }

    private MealBookingService Service(DateTime utcNow) => new(
        _bookings.Object,
        _sessions.Object,
