        CompanyShare = 40,
        EmployeeShare = 10,
        AdhocCompanyShare = 45,
        AdhocEmployeeShare = 15,
        SessionNameNavigation = new HrCmsSessionName { SessionName = name }
    };

    private static HrCmsMealBooking Booking(long id, DateOnly date) => new()
    {
        BookingId = id,
        EmployeeMasterId = EmployeeId,
        MSessionId = Lunch,
        MealDate = date,
        CanteenFacilityType = CanteenFacilityTypes.Daily,
        Status = MealBookingStatuses.Booked,
        MealSession = Session(Lunch, "Lunch", new TimeOnly(12, 0), isActive: true)
    };

    private sealed class FixedClock(DateTime utcNow) : TimeProvider
    {
        public override DateTimeOffset GetUtcNow() => new(utcNow, TimeSpan.Zero);
    }
}

