    public async Task<(ResponseModel, MealPlannerModel?)> GetMealPlannerAsync(DateOnly? fromDate, DateOnly? toDate)
    {
        var (response, employee) = await GetLoggedInEmployeeAsync();
        if (employee == null)
            return (response, null);

        var zone = ResolveTimeZone(employee);
        var today = DateOnly.FromDateTime(TimeZoneLookup.FromUtc(UtcNow, zone));
        var from = fromDate ?? today;
        var to = toDate ?? from.AddDays(DefaultPlannerDays - 1);

        if (to < from)
            return (Fail(HttpStatusCode.BadRequest, "toDate must be on or after fromDate."), null);

        if (to.DayNumber - from.DayNumber + 1 > _settings.MaxRangeDays)
            return (Fail(HttpStatusCode.BadRequest, $"The date range can be at most {_settings.MaxRangeDays} days."), null);

        var nowUtc = UtcNow;
        var facilityType = CanteenMealRates.FacilityTypeOf(employee);

        // Only active sessions: an inactive one cannot be booked, so showing it would be an empty promise.
        var sessions = (await _mealSessionRepository.GetAllAsync())
            .Where(x => x.IsActive)
            .OrderBy(x => x.StartTime)
            .ToList();
        var sessionIds = sessions.Select(x => x.MSessionId).ToList();

        var menuItems = (await _repository.GetMenuItemsAsync(from, to, sessionIds))
            .GroupBy(x => (x.MealDate, x.MSessionId))
            .ToDictionary(g => g.Key, g => g.Select(x => x.ItemName).ToList());

        var bookings = (await _repository.GetBookedAsync(employee.EmployeeMasterId, from, to))
            .GroupBy(x => (x.MealDate, x.MSessionId))
            // One active booking per meal is enforced by UX_HR_CMS_MealBooking_ActiveMeal; First is only
            // here so a duplicate slipped in by hand could never throw the whole screen away.
            .ToDictionary(g => g.Key, g => g.First());

        var planner = new MealPlannerModel
        {
            FromDate = from,
            ToDate = to,
            Today = today,
            IsCanteenFacility = employee.IsCanteenFacility,
            CanteenFacilityType = facilityType,
            FacilityMessage = employee.IsCanteenFacility ? null : CanteenMealRates.FacilityNotEnabledMessage,
            Sessions = sessions.Select(session =>
            {
                var (companyShare, employeeShare) = CanteenMealRates.For(session, facilityType);
                return new MealPlannerSessionModel
                {
                    MSessionId = session.MSessionId,
                    SessionName = session.SessionNameNavigation?.SessionName ?? string.Empty,
                    StartTime = FormatClock(session.StartTime),
                    EndTime = FormatClock(session.EndTime),
                    OrderCutoffDescription = MealOrderCutoff.Describe(session.OrderCutoffTime, session.OrderCutoffDaysBefore),

