import { Component, EventEmitter, Input, Output } from '@angular/core';
import { CurrencyPipe } from '@angular/common';
import { MealPlannerCell } from '../meal-booking.models';

/**
 * One meal on one day, as a button.
 *
 * The same cell is used by the week grid and by the phone's day stack - the two layouts differ, what
 * a cell says and does must not. Only `showSessionName` differs between them: the grid has a column
 * of session headings, the stack has no room for one.
 */
@Component({
  selector: 'app-meal-cell',
  standalone: true,
  imports: [CurrencyPipe],
  templateUrl: './meal-cell.component.html',
  styleUrls: ['./meal-cell.component.scss'],
})
export class MealCellComponent {
  @Input({ required: true }) cell!: MealPlannerCell;
  /** Ticked to be booked. */
  @Input() picked = false;
  /** Ticked to be cancelled. */
  @Input() dropping = false;
  /** The day stack repeats the session name; the grid names it once in its own column. */
  @Input() showSessionName = false;
  @Input() disabled = false;

  @Output() toggled = new EventEmitter<void>();

  /** Doing nothing on tap must not look like a button that failed - say so with the cursor too. */
  get isActionable(): boolean {
    return !this.disabled && (this.cell.canBook || this.cell.canCancel);
  }

  get stateClass(): string {
    return `meal-cell--${this.cell.status.toLowerCase()}`;
  }

  /** Breakfast on 27 Oct, booked, 15 rupees - one sentence for a screen reader, which cannot see
   * the colour the state is otherwise carried by. */
  get ariaLabel(): string {
    return `${this.cell.sessionName}. ${this.cell.statusMessage}`;
  }

  onClick(): void {
    if (this.isActionable) {
      this.toggled.emit();
    }
  }
}
