cat > meal-cell.component.html <<'EOF'
<button
  type="button"
  class="meal-cell"
  [class]="stateClass"
  [class.meal-cell--picked]="picked"
  [class.meal-cell--dropping]="dropping"
  [class.meal-cell--idle]="!isActionable"
  [attr.aria-pressed]="cell.canBook || cell.canCancel ? picked || dropping : null"
  [attr.aria-label]="ariaLabel"
  [disabled]="!isActionable"
  (click)="onClick()"
>
  @if (showSessionName) {
    <span class="meal-cell__session">{{ cell.sessionName }}</span>
  }

  @if (cell.hasMenu) {
    <span class="meal-cell__items">{{ cell.items.join(', ') }}</span>
  } @else {
    <span class="meal-cell__items meal-cell__items--none">No menu</span>
  }

  <span class="meal-cell__foot">
    @if (cell.hasMenu) {
      <span class="meal-cell__price">{{ cell.employeeShare | currency: 'INR' : 'symbol-narrow' : '1.0-2' }}</span>
    }
    <span class="meal-cell__mark" aria-hidden="true">
      @if (dropping) {
        <i class="fa-solid fa-xmark"></i>
      } @else if (picked) {
        <i class="fa-solid fa-check"></i>
      } @else if (cell.isBooked) {
        <i class="fa-solid fa-circle-check"></i>
      } @else if (cell.canBook) {
        <i class="fa-regular fa-square"></i>
      } @else if (cell.status === 'Closed') {
        <i class="fa-solid fa-lock"></i>
      }
    </span>
  </span>

  <!-- Printed, never a tooltip: a phone has no hover, and this is the one place the employee is
       told why a meal is not available. -->
  <span class="meal-cell__why">{{ cell.statusMessage }}</span>
</button>
