/* One meal, as a button. Sized for a thumb first: 44px is the smallest target a finger hits
   reliably, so the whole cell is the hit area rather than a tick box inside it. */
:host {
  display: block;
  height: 100%;
}

.meal-cell {
  width: 100%;
  height: 100%;
  min-height: 72px;
  display: flex;
  flex-direction: column;
  gap: 4px;
  padding: 10px;
  text-align: left;
  background: var(--card-bg);
  border: 1px solid var(--card-border);
  border-radius: 8px;
  color: var(--text-main);
  font: inherit;
  cursor: pointer;
  transition:
    border-color 0.15s ease,
    background 0.15s ease,
    box-shadow 0.15s ease;

  &:focus-visible {
    outline: 2px solid var(--accent);
    outline-offset: 2px;
  }
}

/* Hover is a desktop nicety. Everything the hover states say is also said in text, because a
   touch screen never triggers them. */
@media (hover: hover) {
  .meal-cell:not(.meal-cell--idle):hover {
    border-color: var(--accent-soft-border);
    background: var(--accent-soft);
  }
}

.meal-cell--idle {
  cursor: default;
  background: var(--row-alt);
  color: var(--text-soft);
}

.meal-cell--nomenu {
  background: repeating-linear-gradient(
    135deg,
    var(--row-alt),
    var(--row-alt) 6px,
    #f3f5f8 6px,
    #f3f5f8 12px
  );
}

.meal-cell--closed {
  opacity: 0.72;
}

.meal-cell--booked {
  border-color: #86c7a0;
  background: #f1faf4;
  color: var(--text-main);
}

/* Picked to book, and picked to drop, must never be told apart by colour alone - each carries its
   own icon in .meal-cell__mark. */
.meal-cell--picked {
  border-color: var(--accent);
  background: var(--accent-soft);
  box-shadow: inset 0 0 0 1px var(--accent);
}

.meal-cell--dropping {
  border-color: #d9534f;
  background: #fdf2f2;
  box-shadow: inset 0 0 0 1px #d9534f;
}

.meal-cell__session {
  font-size: 0.75rem;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.02em;
  color: var(--text-soft);
}

.meal-cell__items {
  font-size: 0.8125rem;
  line-height: 1.3;
  font-weight: 500;
  overflow-wrap: anywhere;
}

.meal-cell__items--none {
  font-weight: 400;
  font-style: italic;
  color: var(--text-muted);
}

.meal-cell__foot {
  margin-top: auto;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 8px;
}

.meal-cell__price {
  font-size: 0.8125rem;
  font-weight: 600;
}

.meal-cell__mark {
  font-size: 0.875rem;
  line-height: 1;

  .fa-circle-check {
    color: #2e8b57;
  }
  .fa-check {
    color: var(--accent);
  }
  .fa-xmark {
    color: #d9534f;
  }
  .fa-square {
    color: var(--text-muted);
  }
  .fa-lock {
    color: var(--text-muted);
  }
}

.meal-cell__why {
  font-size: 0.6875rem;
  line-height: 1.25;
  color: var(--text-soft);
}

/* In the week grid the reason would push every row out of alignment, so it is kept for the screen
   reader and shown only where there is room for it - the phone's day stack, which sets
   .meal-cell--roomy through :host-context. */
.meal-cell__why {
  position: absolute;
  width: 1px;
  height: 1px;
  padding: 0;
  margin: -1px;
  overflow: hidden;
  clip: rect(0, 0, 0, 0);
  white-space: nowrap;
  border: 0;
}

:host-context(.mb-stack) .meal-cell__why {
  position: static;
  width: auto;
  height: auto;
  margin: 0;
  overflow: visible;
  clip: auto;
  white-space: normal;
}

:host-context(.mb-stack) .meal-cell {
  min-height: 88px;
  padding: 12px;
}

:host-context(.mb-stack) .meal-cell__items {
  font-size: 0.875rem;
}
