import { Component, OnInit } from '@angular/core';
import { CurrencyPipe } from '@angular/common';
import { finalize } from 'rxjs/operators';
import { ApiService } from '../../../services/api.service';
import { AuthService } from '../../../services/auth.service';
import { ChipNavigationService } from '../../../services/ChipNavigation.service';
import { ToastService } from '../../../services/toaster.service';
import { MealCellComponent } from './meal-cell/meal-cell.component';
import { MyBookingsComponent } from './my-bookings/my-bookings.component';
import {
  BookMealResult,
  CancelMealResult,
  MealPlanner,
  MealPlannerCell,
  MealPlannerDay,
} from './meal-booking.models';

/**
 * The employee's own meal booking screen.
 *
 * One week at a time, because a week is how a canteen is planned and how much fits on a screen
 * without scrolling. The same week is drawn two ways: a day-by-session grid from 768px up, and a
 * single day's cards below it, where seven columns cannot be read or tapped. Both render
 * <app-meal-cell>, so the two layouts can never disagree about what a meal costs or whether it can
 * still be ordered.
 *
 * Nothing about a deadline is worked out here. GetMealPlanner answers it in the canteen's time zone
 * and hands over `canBook` / `canCancel` / `statusMessage` already decided - see
 * Specs/CANTEEN_MEAL_ORDERING_DEADLINE.md for why the rule shown and the rule enforced have to be
 * the same one.
 */
@Component({
  selector: 'app-meal-booking',
  standalone: true,
  imports: [CurrencyPipe, MealCellComponent, MyBookingsComponent],
  templateUrl: './meal-booking.component.html',
  styleUrls: ['./meal-booking.component.scss'],
})
export class MealBookingComponent implements OnInit {
  view: 'book' | 'mine' = 'book';
  planner: MealPlanner | null = null;
  isLoading = false;
  isSaving = false;

  /** Monday of the week on screen, yyyy-MM-dd. */
  weekStart = '';
  /** Which day the phone layout is showing; ignored by the grid. */
  activeDayIndex = 0;

  /** Meals ticked to book, keyed "yyyy-MM-dd|mSessionId". */
  private readonly picked = new Set<string>();
  /** Bookings ticked to cancel, by bookingId. */
  private readonly dropping = new Set<number>();

  constructor(
    private api: ApiService,
    private toast: ToastService,
    private chipService: ChipNavigationService,
    private authService: AuthService,
  ) {
    this.chipService.addTab({ title: 'Meal Booking', route: '/canteen-management/meal-booking' });
    this.authService.ScreenName = 'Meal Booking';
  }

  ngOnInit(): void {
    // The browser's date only picks which week to ask for - a window, not a rule. Every deadline in
    // it comes back already decided in the canteen's zone.
    this.weekStart = this.mondayOf(new Date());
    this.load();
  }

  // ── loading ──────────────────────────────────────────────────────────────────────────────────

  load(): void {
    this.isLoading = true;
    this.clearSelection();
    this.api
      .get('/api/MealBooking/GetMealPlanner', {
        fromDate: this.weekStart,
        toDate: this.addDays(this.weekStart, 6),
      })
      .pipe(finalize(() => (this.isLoading = false)))
      .subscribe({
        next: (res: unknown) => {
          const body = res as Record<string, unknown>;
          this.planner = (body['data'] ?? body['Data'] ?? null) as MealPlanner | null;
          this.activeDayIndex = this.defaultDayIndex();
        },
        error: () => {
          this.planner = null;
        },
      });
  }

  /** Open on today when today is in the week on screen, otherwise on its first day. */
  private defaultDayIndex(): number {
    const index = this.planner?.days.findIndex((d) => d.isToday) ?? -1;
    return index >= 0 ? index : 0;
  }

  // ── week navigation ──────────────────────────────────────────────────────────────────────────

  get weekLabel(): string {
    if (!this.planner?.days.length) {
      return '';
    }
    const days = this.planner.days;
    return `${days[0].dateLabel} – ${days[days.length - 1].dateLabel}`;
  }

  get isCurrentWeek(): boolean {
    return !!this.planner?.days.some((d) => d.isToday);
  }

  shiftWeek(weeks: number): void {
    this.weekStart = this.addDays(this.weekStart, weeks * 7);
    this.load();
  }

  goToThisWeek(): void {
    this.weekStart = this.mondayOf(new Date());
    this.load();
  }

  setView(view: 'book' | 'mine'): void {
    this.view = view;
  }

  setActiveDay(index: number): void {
    this.activeDayIndex = index;
  }

  get activeDay(): MealPlannerDay | null {
    return this.planner?.days[this.activeDayIndex] ?? null;
  }

  // ── selection ────────────────────────────────────────────────────────────────────────────────

  private keyOf(day: MealPlannerDay, cell: MealPlannerCell): string {
    return `${day.mealDate}|${cell.mSessionId}`;
  }

  isPicked(day: MealPlannerDay, cell: MealPlannerCell): boolean {
    return this.picked.has(this.keyOf(day, cell));
  }

  isDropping(cell: MealPlannerCell): boolean {
    return cell.bookingId != null && this.dropping.has(cell.bookingId);
  }

  /** One tap, two meanings, decided by what the cell already is: a free meal is ticked to book, a
   * booked one is ticked to drop. Both are undone by tapping again, and neither commits anything
   * until the action bar is used. */
  toggle(day: MealPlannerDay, cell: MealPlannerCell): void {
    if (cell.canBook) {
      const key = this.keyOf(day, cell);
      this.picked.has(key) ? this.picked.delete(key) : this.picked.add(key);
      return;
    }
    if (cell.canCancel && cell.bookingId != null) {
      this.dropping.has(cell.bookingId)
        ? this.dropping.delete(cell.bookingId)
        : this.dropping.add(cell.bookingId);
    }
  }

  private clearSelection(): void {
    this.picked.clear();
    this.dropping.clear();
  }

  get pickedCount(): number {
    return this.picked.size;
  }

  get droppingCount(): number {
    return this.dropping.size;
  }

  get hasSelection(): boolean {
    return this.picked.size > 0 || this.dropping.size > 0;
  }

  /** What the ticked meals come to for this employee - the figure the action bar shows before
   * anything is committed. */
  get pickedTotal(): number {
    let total = 0;
    for (const day of this.planner?.days ?? []) {
      for (const cell of day.meals) {
        if (this.picked.has(this.keyOf(day, cell))) {
          total += cell.employeeShare;
        }
      }
    }
    return total;
  }

  // ── committing ───────────────────────────────────────────────────────────────────────────────

  book(): void {
    if (!this.picked.size || this.isSaving) {
      return;
    }
    // items[] names each meal. The older mSessionIds x dates shape is every session on every date,
    // which cannot express "breakfast Monday, lunch Tuesday" without also ordering breakfast Tuesday.
    const items = [...this.picked].map((key) => {
      const [mealDate, mSessionId] = key.split('|');
      return { mealDate, mSessionId: Number(mSessionId) };
    });

    this.isSaving = true;
    this.api
      .post('/api/MealBooking/BookMeals', { items })
      .pipe(finalize(() => (this.isSaving = false)))
      .subscribe({
        next: (res: unknown) => {
          const body = res as Record<string, unknown>;
          const results = (body['data'] ?? body['Data'] ?? []) as BookMealResult[];
          this.reportBooking(results);
          this.load();
        },
        error: (err: unknown) => this.reportError(err, 'Could not book these meals.'),
      });
  }

  cancel(): void {
    if (!this.dropping.size || this.isSaving) {
      return;
    }
    this.isSaving = true;
    this.api
      .post('/api/MealBooking/CancelMeals', { bookingIds: [...this.dropping] })
      .pipe(finalize(() => (this.isSaving = false)))
      .subscribe({
        next: (res: unknown) => {
          const body = res as Record<string, unknown>;
          const results = (body['data'] ?? body['Data'] ?? []) as CancelMealResult[];
          this.reportCancel(results);
          this.load();
        },
        error: (err: unknown) => this.reportError(err, 'Could not cancel these bookings.'),
      });
  }

  /**
   * A 200 does not mean everything was booked - each meal carries its own outcome, and a request
   * can come back part booked, part refused. Saying "Saved" over the top of that would hide the
   * refusals, so every distinct outcome is counted and named.
   */
  private reportBooking(results: BookMealResult[]): void {
    const booked = results.filter((r) => r.status === 'Booked').length;
    const refused = results.filter((r) => r.status !== 'Booked');

    if (booked && !refused.length) {
      this.toast.success(`${booked} meal${booked === 1 ? '' : 's'} booked.`);
      return;
    }

    const reasons = this.tally(refused.map((r) => r.status));
    if (booked) {
      this.toast.warning(`${booked} of ${results.length} meals booked. ${reasons}`);
    } else {
      this.toast.error(`No meals were booked. ${reasons}`);
    }
  }

  private reportCancel(results: CancelMealResult[]): void {
    const cancelled = results.filter((r) => r.status === 'Cancelled').length;
    const refused = results.filter((r) => r.status !== 'Cancelled');

    if (cancelled && !refused.length) {
      this.toast.success(`${cancelled} booking${cancelled === 1 ? '' : 's'} cancelled.`);
      return;
    }

    const reasons = this.tally(refused.map((r) => r.status));
    if (cancelled) {
      this.toast.warning(`${cancelled} of ${results.length} bookings cancelled. ${reasons}`);
    } else {
      this.toast.error(`Nothing was cancelled. ${reasons}`);
    }
  }

  /** "2 already booked, 1 booking closed" - the refusals named, not just counted. */
  private tally(statuses: string[]): string {
    const counts = new Map<string, number>();
    for (const status of statuses) {
      counts.set(status, (counts.get(status) ?? 0) + 1);
    }
    return [...counts].map(([status, n]) => `${n} ${status.toLowerCase()}`).join(', ') + '.';
  }

  private reportError(err: unknown, fallback: string): void {
    const message = (err as { error?: { message?: string } })?.error?.message;
    this.toast.error(message || fallback);
  }

  // ── dates ────────────────────────────────────────────────────────────────────────────────────

  /** yyyy-MM-dd from a local Date, without going through UTC - toISOString() would shift the day
   * backwards for anyone east of Greenwich after mid-afternoon. */
  private toIso(date: Date): string {
    const month = `${date.getMonth() + 1}`.padStart(2, '0');
    const day = `${date.getDate()}`.padStart(2, '0');
    return `${date.getFullYear()}-${month}-${day}`;
  }

  private mondayOf(date: Date): string {
    const monday = new Date(date.getFullYear(), date.getMonth(), date.getDate());
    // getDay() is 0 on Sunday, which belongs to the week that started six days earlier.
    const offset = (monday.getDay() + 6) % 7;
    monday.setDate(monday.getDate() - offset);
    return this.toIso(monday);
  }

  private addDays(iso: string, days: number): string {
    const [year, month, day] = iso.split('-').map(Number);
    const shifted = new Date(year, month - 1, day + days);
    return this.toIso(shifted);
  }
}
