  }

  /** What the ticked meals come to for this employee - the figure the action bar shows before
   * anything is committed. */
  get pickedTotal(): number {
    let total = 0;
    for (const day of this.planner?.days ?? []) {
      for (const cell of day.meals) {
        if (this.picked.has(this.keyOf(day, cell))) {
          total += cell.employeeShare;
        }
      }
    }
    return total;
  }

  // ── committing ───────────────────────────────────────────────────────────────────────────────

  book(): void {
    if (!this.picked.size || this.isSaving) {
      return;
    }
    // items[] names each meal. The older mSessionIds x dates shape is every session on every date,
    // which cannot express "breakfast Monday, lunch Tuesday" without also ordering breakfast Tuesday.
    const items = [...this.picked].map((key) => {
      const [mealDate, mSessionId] = key.split('|');
      return { mealDate, mSessionId: Number(mSessionId) };
    });

    this.isSaving = true;
    this.api
      .post('/api/MealBooking/BookMeals', { items })
      .pipe(finalize(() => (this.isSaving = false)))
      .subscribe({
        next: (res: unknown) => {
          const body = res as Record<string, unknown>;
          const results = (body['data'] ?? body['Data'] ?? []) as BookMealResult[];
          this.reportBooking(results);
          this.load();
        },
        error: (err: unknown) => this.reportError(err, 'Could not book these meals.'),
      });
  }

  cancel(): void {
    if (!this.dropping.size || this.isSaving) {
      return;
    }
    this.isSaving = true;
    this.api
      .post('/api/MealBooking/CancelMeals', { bookingIds: [...this.dropping] })
      .pipe(finalize(() => (this.isSaving = false)))
      .subscribe({
        next: (res: unknown) => {
          const body = res as Record<string, unknown>;
          const results = (body['data'] ?? body['Data'] ?? []) as CancelMealResult[];
          this.reportCancel(results);
          this.load();
        },
        error: (err: unknown) => this.reportError(err, 'Could not cancel these bookings.'),
      });
  }

  /**
   * A 200 does not mean everything was booked - each meal carries its own outcome, and a request
   * can come back part booked, part refused. Saying "Saved" over the top of that would hide the
   * refusals, so every distinct outcome is counted and named.
   */
  private reportBooking(results: BookMealResult[]): void {
    const booked = results.filter((r) => r.status === 'Booked').length;
    const refused = results.filter((r) => r.status !== 'Booked');

    if (booked && !refused.length) {
      this.toast.success(`${booked} meal${booked === 1 ? '' : 's'} booked.`);
      return;
    }

    const reasons = this.tally(refused.map((r) => r.status));
    if (booked) {
      this.toast.warning(`${booked} of ${results.length} meals booked. ${reasons}`);
    } else {
      this.toast.error(`No meals were booked. ${reasons}`);
    }
  }

  private reportCancel(results: CancelMealResult[]): void {
    const cancelled = results.filter((r) => r.status === 'Cancelled').length;
    const refused = results.filter((r) => r.status !== 'Cancelled');

    if (cancelled && !refused.length) {
      this.toast.success(`${cancelled} booking${cancelled === 1 ? '' : 's'} cancelled.`);
      return;
    }

    const reasons = this.tally(refused.map((r) => r.status));
    if (cancelled) {
      this.toast.warning(`${cancelled} of ${results.length} bookings cancelled. ${reasons}`);
    } else {
      this.toast.error(`Nothing was cancelled. ${reasons}`);
    }
  }

  /** "2 already booked, 1 booking closed" - the refusals named, not just counted. */
  private tally(statuses: string[]): string {
    const counts = new Map<string, number>();
    for (const status of statuses) {
      counts.set(status, (counts.get(status) ?? 0) + 1);
    }
    return [...counts].map(([status, n]) => `${n} ${status.toLowerCase()}`).join(', ') + '.';
  }

  private reportError(err: unknown, fallback: string): void {
    const message = (err as { error?: { message?: string } })?.error?.message;
    this.toast.error(message || fallback);
  }

  // ── dates ────────────────────────────────────────────────────────────────────────────────────

  /** yyyy-MM-dd from a local Date, without going through UTC - toISOString() would shift the day
   * backwards for anyone east of Greenwich after mid-afternoon. */
  private toIso(date: Date): string {
    const month = `${date.getMonth() + 1}`.padStart(2, '0');
    const day = `${date.getDate()}`.padStart(2, '0');
    return `${date.getFullYear()}-${month}-${day}`;
  }

  private mondayOf(date: Date): string {
    const monday = new Date(date.getFullYear(), date.getMonth(), date.getDate());
    // getDay() is 0 on Sunday, which belongs to the week that started six days earlier.
    const offset = (monday.getDay() + 6) % 7;
    monday.setDate(monday.getDate() - offset);
    return this.toIso(monday);
  }

  private addDays(iso: string, days: number): string {
    const [year, month, day] = iso.split('-').map(Number);
    const shifted = new Date(year, month - 1, day + days);
    return this.toIso(shifted);
  }
}
