  border-radius: 999px;
  background: var(--accent-soft);
  border: 1px solid var(--accent-soft-border);
  color: var(--accent-dark);
  font-size: 0.75rem;
  font-weight: 600;
  white-space: nowrap;
}

/* ── toolbar ─────────────────────────────────────────────────────────────────────────────────── */

.mb-toolbar {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
