  background: var(--card-bg);
}

.mb-segmented__btn {
  min-height: 36px;
  padding: 0 14px;
  border: 0;
  border-radius: 6px;
  background: transparent;
  color: var(--text-secondary);
  font-size: 0.8125rem;
  font-weight: 600;
  cursor: pointer;

  &--on {
    background: var(--accent);
    color: #fff;
  }

  &:focus-visible {
    outline: 2px solid var(--accent);
    outline-offset: 2px;
  }
}

.mb-weeknav {
  display: flex;
  align-items: center;
  gap: 6px;
}

.mb-weeknav__arrow {
  width: 36px;
  height: 36px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  border: 1px solid var(--card-border);
  border-radius: 8px;
  background: var(--card-bg);
  color: var(--text-secondary);
  cursor: pointer;

  &:disabled {
    opacity: 0.5;
    cursor: default;
  }
}

.mb-weeknav__label {
  min-width: 128px;
  text-align: center;
  font-size: 0.8125rem;
  font-weight: 600;
  color: var(--text-main);
}

.mb-weeknav__today {
  min-height: 36px;
  padding: 0 12px;
  border: 1px solid var(--card-border);
  border-radius: 8px;
  background: var(--card-bg);
  color: var(--text-secondary);
  font-size: 0.8125rem;
  font-weight: 600;
  cursor: pointer;

  &:disabled {
    opacity: 0.5;
    cursor: default;
  }
}

/* ── body ────────────────────────────────────────────────────────────────────────────────────── */

.mb-body {
  padding: 16px;
}

.mb-note {
  margin: 0;
  padding: 24px 0;
  text-align: center;
  color: var(--text-soft);
}

.mb-banner {
  display: flex;
  align-items: flex-start;
  gap: 8px;
  margin-bottom: 12px;
  padding: 10px 12px;
  border: 1px solid var(--accent-soft-border);
  border-radius: 8px;
  background: var(--accent-soft);
  color: var(--text-secondary);
  font-size: 0.8125rem;
}

/* ── the week grid (>= 768px) ────────────────────────────────────────────────────────────────── */

.mb-grid {
  display: none;
}

.mb-stack {
  display: block;
}

@media (min-width: 768px) {
  .mb-grid {
    display: grid;
    /* One fixed column of meal names, then a column per day. The day count comes from the template
       as --mb-day-count, so a canteen with a six-day week needs no CSS change. */
    grid-template-columns: minmax(136px, 172px) repeat(var(--mb-day-count, 7), minmax(140px, 1fr));
    gap: 6px;
    /* Between 768px and roughly 1100px seven columns do not fit at a readable width, so the grid
       scrolls sideways and the meal-name column stays put. */
    overflow-x: auto;
    padding-bottom: 4px;
    scroll-snap-type: x proximity;
  }

  .mb-stack {
    display: none;
  }
}

.mb-grid__corner,
.mb-grid__sess {
  position: sticky;
  left: 0;
  z-index: 2;
  background: var(--card-bg);
}

.mb-grid__sess {
  display: flex;
  flex-direction: column;
  gap: 2px;
  justify-content: center;
  padding: 10px 10px 10px 0;
  border-right: 1px solid var(--card-border);
