.mb-grid__sess-name {
  font-size: 0.875rem;
  font-weight: 700;
  color: var(--text-main);
}

.mb-grid__sess-time {
  font-size: 0.75rem;
  color: var(--text-soft);
}

.mb-grid__sess-cut {
  font-size: 0.6875rem;
  line-height: 1.3;
  color: var(--text-muted);
}

.mb-grid__head {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 1px;
  padding: 8px 4px;
  border-bottom: 2px solid transparent;
  scroll-snap-align: start;

  &--today {
    border-bottom-color: var(--accent);
  }
}

.mb-grid__day {
  font-size: 0.75rem;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.03em;
  color: var(--text-secondary);
}

.mb-grid__date {
  font-size: 0.75rem;
  color: var(--text-soft);
}

.mb-grid__head--today .mb-grid__day,
.mb-grid__head--today .mb-grid__date {
  color: var(--accent-dark);
}

/* ── the day stack (< 768px) ─────────────────────────────────────────────────────────────────── */

.mb-chips {
  display: flex;
  gap: 6px;
  margin-bottom: 12px;
  padding-bottom: 4px;
  overflow-x: auto;
  scroll-snap-type: x mandatory;
  -webkit-overflow-scrolling: touch;
}

.mb-chip {
  flex: 0 0 auto;
  min-width: 58px;
  min-height: 56px;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 1px;
  padding: 6px 8px;
  border: 1px solid var(--card-border);
  border-radius: 10px;
  background: var(--card-bg);
  color: var(--text-secondary);
  cursor: pointer;
  scroll-snap-align: center;

  &--today {
    border-color: var(--accent-soft-border);
  }

  &--active {
    background: var(--accent);
    border-color: var(--accent);
    color: #fff;
  }

  &:focus-visible {
    outline: 2px solid var(--accent);
    outline-offset: 2px;
  }
}

.mb-chip__day {
  font-size: 0.6875rem;
  font-weight: 700;
  text-transform: uppercase;
}

.mb-chip__date {
  font-size: 0.75rem;
  font-weight: 600;
}

/* The dot says "you have something booked that day" while the cells themselves are off screen. */
.mb-chip__dot {
  width: 5px;
  height: 5px;
  margin-top: 2px;
  border-radius: 50%;
  background: transparent;

  &--on {
    background: #2e8b57;
  }
}

.mb-chip--active .mb-chip__dot--on {
  background: #fff;
}

.mb-stack__cards {
  display: flex;
  flex-direction: column;
  gap: 10px;
}

/* ── action bar ──────────────────────────────────────────────────────────────────────────────── */

.mb-actionbar {
  position: sticky;
  bottom: 0;
  z-index: 5;
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  justify-content: space-between;
  gap: 10px;
  margin-top: 12px;
  padding: 10px 16px;
  border: 1px solid var(--card-border);
  border-radius: 10px;
  background: var(--card-bg);
  box-shadow: var(--shadow-elevated);
}

.mb-actionbar__summary {
  display: flex;
  flex-wrap: wrap;
  gap: 10px;
}

.mb-actionbar__count {
  font-size: 0.875rem;
  font-weight: 600;
  color: var(--text-main);

  &--drop {
    color: #b02a26;
  }
}

.mb-actionbar__buttons {
  display: flex;
  gap: 8px;
}

.mb-btn {
  min-height: 44px;
  padding: 0 18px;
  border: 1px solid transparent;
  border-radius: 8px;
  font-size: 0.875rem;
  font-weight: 700;
  cursor: pointer;

  &:disabled {
    opacity: 0.6;
    cursor: default;
  }

  &:focus-visible {
    outline: 2px solid var(--text-main);
    outline-offset: 2px;
  }
}

.mb-btn--primary {
  background: var(--accent);
  color: #fff;
}

.mb-btn--danger {
  background: #fff;
  border-color: #d9534f;
  color: #b02a26;
}

@media (max-width: 767.98px) {
  .mb-body {
    padding: 12px;
  }

  .mb-toolbar {
    padding: 10px 12px;
  }

  .mb-segmented,
  .mb-segmented__btn {
    flex: 1 1 auto;
  }

  .mb-weeknav {
    width: 100%;
    justify-content: space-between;
  }

  .mb-weeknav__label {
    flex: 1 1 auto;
  }

  /* Off the page flow and above the home indicator: the bar is the primary action on a phone and
     must not need a scroll to reach. */
  .mb-actionbar {
    position: fixed;
    left: 0;
    right: 0;
    bottom: 0;
    margin: 0;
    border-radius: 0;
    border-left: 0;
    border-right: 0;
    border-bottom: 0;
    padding-bottom: calc(10px + env(safe-area-inset-bottom, 0px));
  }

  .mb-actionbar__buttons {
    flex: 1 1 auto;
  }

  .mb-btn {
    flex: 1 1 auto;
  }

  /* Clears the fixed bar so the last card is always reachable. */
  .meal-booking-page {
    padding-bottom: calc(84px + env(safe-area-inset-bottom, 0px));
  }
}

.visually-hidden {
  position: absolute;
  width: 1px;
  height: 1px;
  padding: 0;
  margin: -1px;
  overflow: hidden;
  clip: rect(0, 0, 0, 0);
  white-space: nowrap;
  border: 0;
}
