}

.mb-btn--danger {
  background: #fff;
  border-color: #d9534f;
  color: #b02a26;
}

@media (max-width: 767.98px) {
  .mb-body {
    padding: 12px;
  }

  .mb-toolbar {
    padding: 10px 12px;
