  .mb-segmented,
  .mb-segmented__btn {
    flex: 1 1 auto;
  }

  .mb-weeknav {
    width: 100%;
    justify-content: space-between;
  }

  .mb-weeknav__label {
    flex: 1 1 auto;
  }

  /* Off the page flow and above the home indicator: the bar is the primary action on a phone and
     must not need a scroll to reach. */
  .mb-actionbar {
    position: fixed;
    left: 0;
    right: 0;
    bottom: 0;
    margin: 0;
    border-radius: 0;
    border-left: 0;
    border-right: 0;
