import { Component, OnInit } from '@angular/core';
import { CurrencyPipe, DatePipe } from '@angular/common';
import { finalize } from 'rxjs/operators';
import { ApiService } from '../../../../services/api.service';
import { MyBooking } from '../meal-booking.models';

interface BookingDay {
  mealDate: string;
  bookings: MyBooking[];
  total: number;
}

/**
 * What the employee has booked, a month at a time - the history behind the planner, and the figure
 * that turns up as a salary deduction.
 *
 * A card list rather than a grid: this is read on a phone more often than at a desk, and a data
 * grid at 375px is a row of ellipses.
 */
@Component({
  selector: 'app-my-bookings',
  standalone: true,
  imports: [CurrencyPipe, DatePipe],
  templateUrl: './my-bookings.component.html',
  styleUrls: ['./my-bookings.component.scss'],
})
export class MyBookingsComponent implements OnInit {
  days: BookingDay[] = [];
  isLoading = false;
  monthLabel = '';
  total = 0;
  mealCount = 0;

  /** First of the month on screen. */
  private month = new Date();

  constructor(private api: ApiService) {}

  ngOnInit(): void {
    this.month = new Date(this.month.getFullYear(), this.month.getMonth(), 1);
    this.load();
  }

  shiftMonth(months: number): void {
    this.month = new Date(this.month.getFullYear(), this.month.getMonth() + months, 1);
    this.load();
  }

  load(): void {
    const from = this.month;
    const to = new Date(this.month.getFullYear(), this.month.getMonth() + 1, 0);
    this.monthLabel = from.toLocaleDateString(undefined, { month: 'long', year: 'numeric' });

    this.isLoading = true;
    this.api
      .get('/api/MealBooking/GetMyBookings', { fromDate: this.toIso(from), toDate: this.toIso(to) })
      .pipe(finalize(() => (this.isLoading = false)))
      .subscribe({
        next: (res: unknown) => {
          const body = res as Record<string, unknown>;
          const raw = body['data'] ?? body['Data'];
          this.group(Array.isArray(raw) ? (raw as MyBooking[]) : []);
        },
        error: () => this.group([]),
      });
  }

  private group(bookings: MyBooking[]): void {
    const byDate = new Map<string, MyBooking[]>();
    for (const booking of bookings) {
      const list = byDate.get(booking.mealDate) ?? [];
      list.push(booking);
      byDate.set(booking.mealDate, list);
    }

    this.days = [...byDate.entries()]
      .sort(([a], [b]) => a.localeCompare(b))
      .map(([mealDate, list]) => ({
        mealDate,
        bookings: list,
        total: list.reduce((sum, b) => sum + b.employeeShare, 0),
      }));

    this.mealCount = bookings.length;
    this.total = bookings.reduce((sum, b) => sum + b.employeeShare, 0);
  }

  /** yyyy-MM-dd from a local Date - toISOString() would shift the day for anyone east of UTC. */
  private toIso(date: Date): string {
    const month = `${date.getMonth() + 1}`.padStart(2, '0');
    const day = `${date.getDate()}`.padStart(2, '0');
    return `${date.getFullYear()}-${month}-${day}`;
  }
}
