import { Component, OnInit } from '@angular/core';
import { DatePipe } from '@angular/common';
import { FormsModule } from '@angular/forms';
import { DxDateBoxModule } from 'devextreme-angular/ui/date-box';
import { DxSelectBoxModule } from 'devextreme-angular/ui/select-box';
import { DxTextBoxModule } from 'devextreme-angular/ui/text-box';
import { DxButtonModule } from 'devextreme-angular/ui/button';
import { finalize } from 'rxjs/operators';
import { CommonGridComponent } from '../../../layout/common-grid/common-grid.component';
import { ApiService } from '../../../services/api.service';
import { AuthService } from '../../../services/auth.service';
import { ChipNavigationService } from '../../../services/ChipNavigation.service';

interface RegisterRow {
  bookingId: number;
  mealDate: string;
  mSessionId: number;
  sessionName: string;
  employeeMasterId: number;
  employeeCode: string;
  employeeName: string;
  canteenFacilityType: string;
  companyShare: number;
  employeeShare: number;
  status: string;
  bookedOn: string;
  cancelledOn: string | null;
}

interface Register {
  fromDate: string;
  toDate: string;
  page: number;
  pageSize: number;
  totalCount: number;
  bookedCount: number;
  cancelledCount: number;
  totalCompanyShare: number;
  totalEmployeeShare: number;
  rows: RegisterRow[];
}

/**
 * The canteen office's view: everybody's bookings for a date range, with the totals the canteen is
 * billed on.
 *
 * Defaults to one day. The API returns at most 500 rows per call, and a company of any size books
 * more meals than that in a month - so the screen says plainly when a range is wider than it can
 * show rather than quietly displaying a prefix of it as if it were the whole thing.
 */
@Component({
  selector: 'app-booking-register',
  standalone: true,
  imports: [
    FormsModule,
    DxDateBoxModule,
    DxSelectBoxModule,
    DxTextBoxModule,
    DxButtonModule,
    CommonGridComponent,
  ],
  templateUrl: './booking-register.component.html',
  styleUrls: ['./booking-register.component.scss'],
})
export class BookingRegisterComponent implements OnInit {
  columns: Record<string, unknown>[] = [];
  data: Record<string, unknown>[] = [];
  register: Register | null = null;
  isLoading = false;

  fromDate: Date = new Date();
  toDate: Date = new Date();
  mSessionId: number | null = null;
  status: string | null = null;
  search = '';

  sessions: { id: number; name: string }[] = [];
  readonly statuses = [
    { id: 'Booked', name: 'Booked' },
    { id: 'Cancelled', name: 'Cancelled' },
  ];

  constructor(
    private api: ApiService,
    private chipService: ChipNavigationService,
    private authService: AuthService,
    private datePipe: DatePipe,
  ) {
    this.chipService.addTab({
      title: 'Bookings Register',
      route: '/canteen-management/booking-register',
    });
    this.authService.ScreenName = 'Bookings Register';
  }

  ngOnInit(): void {
    this.columns = [
      { dataField: 'mealDateText', caption: 'Meal Date', width: 120 },
      { dataField: 'sessionName', caption: 'Meal', width: 120 },
      { dataField: 'employeeCode', caption: 'Code', width: 110 },
      { dataField: 'employeeName', caption: 'Employee' },
      { dataField: 'canteenFacilityType', caption: 'Plan', width: 90 },
      { dataField: 'employeeShare', caption: 'Employee Share', width: 140 },
      { dataField: 'companyShare', caption: 'Company Share', width: 140 },
      { dataField: 'status', caption: 'Status', width: 110 },
      { dataField: 'bookedOnText', caption: 'Booked On', width: 150 },
    ];
    this.loadSessions();
    this.load();
  }

  private loadSessions(): void {
    this.api.get('/api/MealSession/GetAllMealSessions').subscribe({
      next: (res: unknown) => {
        const body = res as Record<string, unknown>;
        const raw = (body['data'] ?? body['Data'] ?? []) as Record<string, unknown>[];
        this.sessions = raw.map((r) => ({
          id: Number(r['mSessionId']),
          name: String(r['sessionName'] ?? ''),
        }));
      },
      error: () => {
        this.sessions = [];
      },
    });
  }

  load(): void {
    this.isLoading = true;
    const params: Record<string, string> = {
      fromDate: this.toIso(this.fromDate),
      toDate: this.toIso(this.toDate),
      page: '1',
      pageSize: '500',
    };
    if (this.mSessionId) {
      params['mSessionId'] = String(this.mSessionId);
    }
    if (this.status) {
      params['status'] = this.status;
    }
    if (this.search.trim()) {
      params['search'] = this.search.trim();
    }

    this.api
      .get('/api/MealBooking/GetBookingRegister', params)
      .pipe(finalize(() => (this.isLoading = false)))
      .subscribe({
        next: (res: unknown) => {
          const body = res as Record<string, unknown>;
          this.register = (body['data'] ?? body['Data'] ?? null) as Register | null;
          this.data = (this.register?.rows ?? []).map((row) => ({
            ...row,
            mealDateText: this.datePipe.transform(row.mealDate, 'dd MMM yyyy') ?? row.mealDate,
            bookedOnText: this.datePipe.transform(row.bookedOn, 'dd MMM, HH:mm') ?? '',
          }));
        },
        error: () => {
          this.register = null;
          this.data = [];
        },
      });
  }

  onRefresh(): void {
    this.load();
  }

  resetFilters(): void {
    this.fromDate = new Date();
    this.toDate = new Date();
    this.mSessionId = null;
    this.status = null;
    this.search = '';
    this.load();
  }

  /** True when the range holds more bookings than one call returns - the grid is then a prefix,
   * and saying so is the difference between a register and a misleading one. */
  get isTruncated(): boolean {
    return !!this.register && this.register.totalCount > this.register.rows.length;
  }

  get gridSubtitle(): string {
    if (!this.register) {
      return 'Canteen management';
    }
    const { bookedCount, cancelledCount } = this.register;
    return `${bookedCount} booked · ${cancelledCount} cancelled · Canteen management`;
  }

  private toIso(date: Date): string {
    const month = `${date.getMonth() + 1}`.padStart(2, '0');
    const day = `${date.getDate()}`.padStart(2, '0');
    return `${date.getFullYear()}-${month}-${day}`;
  }
}
