<div class="page-wrapper booking-register-page">
  <section class="section-card br-filters">
    <div class="section-header">
      <i class="fa-solid fa-filter" aria-hidden="true"></i>
      <span class="header-title">Filters</span>
    </div>
    <div class="section-body row g-2">
      <div class="col-6 col-md-3 col-lg-2">
        <label class="form-label" for="br-from">From</label>
        <dx-date-box
          inputAttr="{ id: 'br-from' }"
          [(value)]="fromDate"
          type="date"
          displayFormat="dd MMM yyyy"
          [disabled]="isLoading"
        ></dx-date-box>
      </div>
      <div class="col-6 col-md-3 col-lg-2">
        <label class="form-label" for="br-to">To</label>
        <dx-date-box
          inputAttr="{ id: 'br-to' }"
          [(value)]="toDate"
          type="date"
          displayFormat="dd MMM yyyy"
          [disabled]="isLoading"
        ></dx-date-box>
      </div>
      <div class="col-6 col-md-3 col-lg-2">
        <label class="form-label">Meal</label>
        <dx-select-box
          [(value)]="mSessionId"
          [items]="sessions"
          displayExpr="name"
          valueExpr="id"
          placeholder="All meals"
          [showClearButton]="true"
          [disabled]="isLoading"
        ></dx-select-box>
      </div>
      <div class="col-6 col-md-3 col-lg-2">
        <label class="form-label">Status</label>
        <dx-select-box
          [(value)]="status"
          [items]="statuses"
          displayExpr="name"
          valueExpr="id"
          placeholder="All"
          [showClearButton]="true"
          [disabled]="isLoading"
        ></dx-select-box>
      </div>
      <div class="col-12 col-lg-3">
        <label class="form-label">Employee</label>
        <dx-text-box
          [(value)]="search"
          placeholder="Code or name"
          [showClearButton]="true"
          [disabled]="isLoading"
          (onEnterKey)="load()"
        ></dx-text-box>
      </div>
      <div class="col-12 col-lg-1 br-filters__actions">
        <dx-button
          text="Apply"
          type="default"
          [disabled]="isLoading"
          (onClick)="load()"
        ></dx-button>
        <dx-button text="Reset" stylingMode="text" [disabled]="isLoading" (onClick)="resetFilters()"></dx-button>
      </div>
    </div>
  </section>

  @if (register) {
    <div class="br-totals">
      <div class="br-total">
        <span class="br-total__label">Meals booked</span>
        <span class="br-total__value">{{ register.bookedCount }}</span>
      </div>
      <div class="br-total">
        <span class="br-total__label">Employee share</span>
        <span class="br-total__value">{{ register.totalEmployeeShare | number: '1.0-2' }}</span>
      </div>
      <div class="br-total">
        <span class="br-total__label">Company share</span>
        <span class="br-total__value">{{ register.totalCompanyShare | number: '1.0-2' }}</span>
      </div>
      <p class="br-totals__note">
        Totals cover every booking matching the filters, not just the rows below, and count booked
        meals only.
      </p>
    </div>
  }

  @if (isTruncated) {
    <div class="br-warning" role="alert">
      <i class="fa-solid fa-triangle-exclamation" aria-hidden="true"></i>
      <span>
        Showing {{ register?.rows?.length }} of {{ register?.totalCount }} bookings. The totals above
        are still for all {{ register?.totalCount }} — but the list is cut short. Narrow the dates,
        or filter by meal or employee, to see every row.
      </span>
    </div>
  }

  <app-common-grid
    class="booking-register-grid"
    [dataSource]="data"
    [columns]="columns"
    [storageKey]="'canteenBookingRegisterGrid'"
    [gridTitle]="'Bookings Register'"
    [gridIcon]="'fa-solid fa-clipboard-list'"
    [gridSubtitle]="gridSubtitle"
    [showRefreshButton]="true"
    [refreshDisabled]="isLoading"
    (refresh)="onRefresh()"
    [showAddButton]="false"
    [allowRowEdit]="false"
    [allowRowDelete]="false"
    [selectionMode]="'none'"
    [fillViewport]="true"
    [columnHidingEnabled]="true"
    [showDetailOnMobile]="true"
    [exportFileName]="'CanteenBookingsRegister.xlsx'"
  >
  </app-common-grid>
</div>
