import { Component, OnInit } from '@angular/core';
import { DecimalPipe } from '@angular/common';
import { finalize } from 'rxjs/operators';
import { ApiService } from '../../../services/api.service';
import { AuthService } from '../../../services/auth.service';
import { ChipNavigationService } from '../../../services/ChipNavigation.service';

interface CountCell {
  mSessionId: number;
  sessionName: string;
  totalMeals: number;
  dailyCount: number;
  adhocCount: number;
  companyShare: number;
  employeeShare: number;
  /** The ordering deadline has passed: this number can no longer move. */
  isFinal: boolean;
}

interface CountDay {
  mealDate: string;
  dayLabel: string;
  dateLabel: string;
  isToday: boolean;
  sessions: CountCell[];
  totalMeals: number;
}

interface BookingCounts {
  fromDate: string;
  toDate: string;
  today: string;
  days: CountDay[];
  sessionTotals: CountCell[];
  totalMeals: number;
  totalCompanyShare: number;
  totalEmployeeShare: number;
}

/**
 * What the kitchen cooks: meals actually booked, per day and per meal session.
 *
 * Every number carries whether it is settled. Until a meal's ordering deadline passes employees can
 * still add and drop it, so a count shown without that distinction would read as a shopping list
 * when it is really a forecast - `isFinal` is the difference, and it is marked on every cell.
 *
 * This is not api/CanteenDashboard/Summary, which counts the people a menu was mailed to.
 */
@Component({
  selector: 'app-canteen-dashboard',
  standalone: true,
  imports: [DecimalPipe],
  templateUrl: './canteen-dashboard.component.html',
  styleUrls: ['./canteen-dashboard.component.scss'],
})
export class CanteenDashboardComponent implements OnInit {
  counts: BookingCounts | null = null;
  isLoading = false;
  weekStart = '';

  constructor(
    private api: ApiService,
    private chipService: ChipNavigationService,
    private authService: AuthService,
  ) {
    this.chipService.addTab({
      title: 'Canteen Dashboard',
      route: '/canteen-management/canteen-dashboard',
    });
    this.authService.ScreenName = 'Canteen Dashboard';
  }

  ngOnInit(): void {
    this.weekStart = this.mondayOf(new Date());
    this.load();
  }

  load(): void {
    this.isLoading = true;
    this.api
      .get('/api/CanteenDashboard/BookingCounts', {
        fromDate: this.weekStart,
        toDate: this.addDays(this.weekStart, 6),
      })
      .pipe(finalize(() => (this.isLoading = false)))
      .subscribe({
        next: (res: unknown) => {
          const body = res as Record<string, unknown>;
          this.counts = (body['data'] ?? body['Data'] ?? null) as BookingCounts | null;
        },
        error: () => {
          this.counts = null;
        },
      });
  }

  shiftWeek(weeks: number): void {
    this.weekStart = this.addDays(this.weekStart, weeks * 7);
    this.load();
  }

  goToThisWeek(): void {
    this.weekStart = this.mondayOf(new Date());
    this.load();
  }

  get isCurrentWeek(): boolean {
    return !!this.counts?.days.some((d) => d.isToday);
  }

  get weekLabel(): string {
    const days = this.counts?.days ?? [];
    return days.length ? `${days[0].dateLabel} – ${days[days.length - 1].dateLabel}` : '';
  }

  /** The session headings, taken from the totals row so the matrix has a stable column order even
   * on a day where nothing at all was booked. */
  get sessions(): CountCell[] {
    return this.counts?.sessionTotals ?? [];
  }

  cellFor(day: CountDay, mSessionId: number): CountCell | null {
    return day.sessions.find((s) => s.mSessionId === mSessionId) ?? null;
  }

  private toIso(date: Date): string {
    const month = `${date.getMonth() + 1}`.padStart(2, '0');
    const day = `${date.getDate()}`.padStart(2, '0');
    return `${date.getFullYear()}-${month}-${day}`;
  }

  private mondayOf(date: Date): string {
    const monday = new Date(date.getFullYear(), date.getMonth(), date.getDate());
    const offset = (monday.getDay() + 6) % 7;
    monday.setDate(monday.getDate() - offset);
    return this.toIso(monday);
  }

  private addDays(iso: string, days: number): string {
    const [year, month, day] = iso.split('-').map(Number);
    return this.toIso(new Date(year, month - 1, day + days));
  }
}
