/* ── toolbar ─────────────────────────────────────────────────────────────────────────────────── */

.cd-toolbar {
  display: flex;
  align-items: center;
  justify-content: flex-end;
  padding: 10px 16px;
  border-bottom: 1px solid var(--card-border);
  background: var(--section-header-bg);
}

.cd-weeknav {
  display: flex;
  align-items: center;
  gap: 6px;
}

.cd-arrow {
  width: 36px;
  height: 36px;
