  align-items: center;
  justify-content: center;
  border: 1px solid var(--card-border);
  border-radius: 8px;
  background: var(--card-bg);
  color: var(--text-secondary);
  cursor: pointer;

  &:disabled {
    opacity: 0.5;
    cursor: default;
  }
}

.cd-weeknav__label {
  min-width: 128px;
  text-align: center;
  font-size: 0.8125rem;
  font-weight: 600;
  color: var(--text-main);
}

.cd-today {
  min-height: 36px;
  padding: 0 12px;
  border: 1px solid var(--card-border);
  border-radius: 8px;
  background: var(--card-bg);
  color: var(--text-secondary);
  font-size: 0.8125rem;
  font-weight: 600;
  cursor: pointer;

  &:disabled {
    opacity: 0.5;
    cursor: default;
  }
}

/* ── tiles ───────────────────────────────────────────────────────────────────────────────────── */

.cd-body {
  padding: 16px;
}

.cd-note {
  margin: 0;
  padding: 24px 0;
  text-align: center;
  color: var(--text-soft);
}

/* auto-fit keeps the tiles honest at every width: four across on a desktop, two on a phone, with
   no breakpoint doing the arithmetic. */
.cd-tiles {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(140px, 1fr));
  gap: 10px;
  margin-bottom: 16px;
}

.cd-tile {
  display: flex;
  flex-direction: column;
  gap: 2px;
  padding: 12px;
  border: 1px solid var(--card-border);
  border-radius: 10px;
  background: var(--card-bg);

  &--accent {
    border-color: var(--accent-soft-border);
    background: var(--accent-soft);
  }
}

.cd-tile__label {
  font-size: 0.6875rem;
  text-transform: uppercase;
  letter-spacing: 0.03em;
  color: var(--text-muted);
}

.cd-tile__value {
  font-size: 1.5rem;
  font-weight: 700;
  line-height: 1.1;
  color: var(--text-main);
}

.cd-tile--accent .cd-tile__value {
  color: var(--accent-dark);
}

.cd-tile__hint {
  font-size: 0.6875rem;
  color: var(--text-soft);
}

/* ── matrix ──────────────────────────────────────────────────────────────────────────────────── */

.cd-matrix-wrap {
  overflow-x: auto;
  -webkit-overflow-scrolling: touch;
}

.cd-matrix {
  width: 100%;
  min-width: 560px;
  border-collapse: separate;
  border-spacing: 0;
  font-size: 0.8125rem;

  th,
  td {
    padding: 8px 10px;
    border-bottom: 1px solid var(--grid-border);
    text-align: center;
    white-space: nowrap;
  }

  thead th {
    background: var(--grid-header-bg);
    color: var(--grid-header-text);
    font-weight: 600;
  }
}

/* The meal name stays put while the week scrolls past it, so a count is never orphaned from its
   row on a narrow screen. */
.cd-matrix__corner,
.cd-matrix__rowhead {
  position: sticky;
  left: 0;
  z-index: 2;
  text-align: left;
  background: var(--card-bg);
  font-weight: 700;
  color: var(--text-main);
}

.cd-matrix__corner {
  background: var(--grid-header-bg);
}

.cd-matrix__day {
  display: block;
  font-size: 0.6875rem;
  text-transform: uppercase;
  letter-spacing: 0.03em;
}

.cd-matrix__date {
  display: block;
  font-size: 0.75rem;
  font-weight: 500;
  color: var(--text-soft);
}

.cd-matrix__today {
  background: var(--accent-soft);
}

.cd-matrix__totals {
  th,
  td {
    border-top: 2px solid var(--grid-border);
    font-weight: 700;
    background: var(--row-alt);
  }

  .cd-matrix__rowhead {
    background: var(--row-alt);
  }
}

.cd-count {
  display: block;
  font-size: 1rem;
  font-weight: 700;
  color: var(--text-main);

  &--zero {
    font-weight: 500;
    color: var(--text-muted);
  }
}

/* A number alone cannot say whether it is settled, and that is the whole difference between a
   shopping list and a forecast - so every non-zero count is labelled in words, not by colour. */
.cd-state {
  display: inline-block;
  margin-top: 2px;
  padding: 1px 6px;
  border-radius: 999px;
  background: var(--row-hover);
  color: var(--text-soft);
  font-size: 0.625rem;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.03em;

  &--final {
    background: #e7f5ec;
    color: #27694a;
  }
}

.cd-legend {
  margin: 12px 0 0;
  font-size: 0.75rem;
  color: var(--text-soft);

  .cd-state {
    margin: 0 2px;
  }
}

@media (max-width: 767.98px) {
  .cd-body {
    padding: 12px;
  }

  .cd-toolbar {
    padding: 10px 12px;
    justify-content: space-between;
  }

  .cd-weeknav {
    width: 100%;
    justify-content: space-between;
  }

  .cd-weeknav__label {
    flex: 1 1 auto;
    min-width: 0;
  }

  .cd-tile__value {
    font-size: 1.25rem;
  }
}

.visually-hidden {
  position: absolute;
  width: 1px;
  height: 1px;
  padding: 0;
  margin: -1px;
  overflow: hidden;
  clip: rect(0, 0, 0, 0);
  white-space: nowrap;
  border: 0;
}
