using Microsoft.EntityFrameworkCore;
using Microsoft.Extensions.Logging;
using SolutionOne_Core.CanteenManagementModels.CanteenDashboard;
using SolutionOne_Core.CanteenManagementModels.MealBooking;
using SolutionOne_DataAccessLayer.Entities;
using SolutionOne_DataAccessLayer.Repositories.Canteen_Management.Interface;

namespace SolutionOne_DataAccessLayer.Repositories.Canteen_Management.Implementation;

public class CanteenDashboardRepository : ICanteenDashboardRepository
{
    private readonly HrmsystemContext _context;
    private readonly ILogger<CanteenDashboardRepository> _logger;

    public CanteenDashboardRepository(HrmsystemContext context, ILogger<CanteenDashboardRepository> logger)
    {
        _context = context;
        _logger = logger;
    }

    // Recipient-count proxy source for the summary tiles: HrCmsMenuPublish rows whose
    // [FromDate, ToDate] range overlaps the requested window. Reach, not meals - see
    // GetBookingCountsAsync for what was actually booked.
    public Task<List<HrCmsMenuPublish>> GetPublishesOverlappingRangeAsync(DateTime fromDate, DateTime toDate)
    {
        var from = fromDate.Date;
        var to = toDate.Date;

        return _context.HrCmsMenuPublishes
            .AsNoTracking()
            .Where(x => x.FromDate.Date <= to && x.ToDate.Date >= from)
            .ToListAsync();
    }

    public async Task<List<CanteenBookingCountRow>> GetBookingCountsAsync(DateOnly fromDate, DateOnly toDate)
    {
        if (toDate < fromDate)
            return new List<CanteenBookingCountRow>();

        return await _context.HrCmsMealBookings
            .AsNoTracking()
            .Where(x => x.Status == MealBookingStatuses.Booked
                        && x.MealDate >= fromDate && x.MealDate <= toDate)
            .GroupBy(x => new { x.MealDate, x.MSessionId, x.CanteenFacilityType })
            .Select(g => new CanteenBookingCountRow
            {
                MealDate = g.Key.MealDate,
                MSessionId = g.Key.MSessionId,
                CanteenFacilityType = g.Key.CanteenFacilityType,
                TotalMeals = g.Count(),
                CompanyShare = g.Sum(x => x.CompanyShare),
                EmployeeShare = g.Sum(x => x.EmployeeShare)
            })
            .ToListAsync();
    }

    public Task<int> GetDistinctPublishCountCreatedInRangeAsync(DateTime fromDate, DateTime toDate)
    {
        var from = fromDate.Date;
        var to = toDate.Date;

        return _context.HrCmsMenuPublishes
            .AsNoTracking()
            .Where(x => x.CreatedDate.Date >= from && x.CreatedDate.Date <= to)
            .Select(x => x.MenuPublishId)
            .Distinct()
            .CountAsync();
    }
}

using Microsoft.Extensions.DependencyInjection;
using SolutionOne_DataAccessLayer.Repositories.Canteen_Management.Implementation;
using SolutionOne_DataAccessLayer.Repositories.Canteen_Management.Interface;

namespace SolutionOne_DataAccessLayer.Middleware.Canteen_Management;

public static class CmsDependencyInjection
{
    public static IServiceCollection AddCmsRepository(this IServiceCollection services)
    {
        services.AddScoped<IMealSessionRepository, MealSessionRepository>();
        services.AddScoped<IItemMasterRepository, ItemMasterRepository>();
        services.AddScoped<IMenuPlanRepository, MenuPlanRepository>();
        services.AddScoped<IMenuPublishRepository, MenuPublishRepository>();
        services.AddScoped<ICanteenDashboardRepository, CanteenDashboardRepository>();
        services.AddScoped<IMealBookingRepository, MealBookingRepository>();
        services.AddScoped<ICanteenConfigRepository, CanteenConfigRepository>();
        return services;
    }
}

